static unsigned char eula_text_0454[] = "der vorstehenden Beschr\303\244nkungen ist nach geltendem Recht verboten oder wird durch die Lizenzbedingungen f\303\274r";
static unsigned char eula_text_0455[] = "die Nutzung von Open-Source-Komponenten gestattet, die im Service enthalten sind).";
static unsigned char eula_text_0456[] = "3. Benachrichtigungen von Aspyr Media";
static unsigned char eula_text_0457[] = "Sie verstehen, dass Sie gesch\303\244ftsbezogene Benachrichtigungen von Aspyr Media \303\274ber den Service oder per E-Mail";
static unsigned char eula_text_0458[] = "erhalten k\303\266nnen, darunter beispielsweise Ank\303\274ndigungen zu Produkten und anderen Themen sowie administrative";
static unsigned char eula_text_0459[] = "Mitteilungen. Sie stimmen darin \303\274berein, dass es sich bei diesen Mitteilungen nicht um \342\200\236unaufgeforderte";
static unsigned char eula_text_0460[] = "kommerzielle E-Mail-Werbung\342\200\234 handelt, und erkl\303\244ren sich damit einverstanden, sie zu erhalten.";
static unsigned char eula_text_0461[] = "Marketingbezogene E-Mail-Nachrichten werden mit Anweisungen zur Abmeldung versehen.";
static unsigned char eula_text_0462[] = "4. Plattformen von Drittanbietern";
static unsigned char eula_text_0463[] = "Auch wenn Sie den Service \303\274ber eine Plattform eines Drittanbieters erworben oder lizenziert haben, wie zum";
static unsigned char eula_text_0464[] = "Beispiel die Steam-Plattform von Valve, den Sony PlayStation Store, die Xbox-Plattform von Microsoft, den";
static unsigned char eula_text_0465[] = "Nintendo eShop, den Apple App Store, den Google Play Store und andere (jeweils eine";
static unsigned char eula_text_0466[] = "\342\200\236Drittanbieter-Plattform\342\200\234), ist keine der Drittanbieter-Plattformen oder deren Eigent\303\274mer eine Partei dieses";
static unsigned char eula_text_0467[] = "Vertrags und hat somit in Verbindung mit dem Service keinerlei Verpflichtungen Ihnen gegen\303\274ber. Dar\303\274ber";
static unsigned char eula_text_0468[] = "hinaus wird mit diesem Vertrag nicht bezweckt, Ihre Beziehung zu einer der Drittplattformen im Rahmen der";
static unsigned char eula_text_0469[] = "geltenden Vereinbarungen der Drittplattformen mit Ihnen zu regeln oder zu \303\244ndern, einschlie\303\237lich etwaiger";
static unsigned char eula_text_0470[] = "Nutzungsbedingungen, EULAs oder sonstiger Vereinbarungen, mit denen eine Drittplattform ihren Nutzern das";
static unsigned char eula_text_0471[] = "Recht zur Installation und Verwendung eines Spiels gew\303\244hrt.";
static unsigned char eula_text_0472[] = "Nutzer der Sony-Plattform: Auch wenn Sie den Service \303\274ber Sony Interactive Entertainment LLC oder eines";
static unsigned char eula_text_0473[] = "seiner gegenw\303\244rtigen oder fr\303\274heren verbundenen Unternehmen, einschlie\303\237lich Mutter- und Tochtergesellschaften,";
static unsigned char eula_text_0474[] = "und jedes Vorg\303\244nger- oder Nachfolgeunternehmen eines der vorgenannten Unternehmen (jedes davon ein";
static unsigned char eula_text_0475[] = "\342\200\236Unternehmen der SIE-Gruppe\342\200\234) erworben oder lizenziert haben, ist kein Unternehmen der SIE-Gruppe eine Partei";
static unsigned char eula_text_0476[] = "dieses Vertrags und kein Unternehmen der SIE-Gruppe hat Ihnen gegen\303\274ber irgendwelche Verpflichtungen im";
static unsigned char eula_text_0477[] = "Zusammenhang mit dem Service. Dieser Vertrag gilt zwischen Aspyr Media und Ihnen, nicht zwischen einem";
static unsigned char eula_text_0478[] = "Unternehmen der SIE-Gruppe und Ihnen. In Bezug auf jedes Unternehmen der SIE-Gruppe ist allein Aspyr Media";
static unsigned char eula_text_0479[] = "f\303\274r den Service verantwortlich. Sie und Aspyr Media erkennen an und stimmen darin \303\274berein, dass jedes";
static unsigned char eula_text_0480[] = "Unternehmen der SIE-Gruppe (oder das Unternehmen der SIE-Gruppe f\303\274r das Gebiet, in dem das lizenzierte";
static unsigned char eula_text_0481[] = "Produkt verkauft wird, wenn der Publisher-EULA nur regional gilt) ein Drittbeg\303\274nstigter dieses Vertrags ist.";
static unsigned char eula_text_0482[] = "Ungeachtet anderslautender Bestimmungen in diesem Vertrag gew\303\244hrt Aspyr Media Ihnen eine eingeschr\303\244nkte";
static unsigned char eula_text_0483[] = "Lizenz zur Nutzung des Service nur auf einem Ger\303\244t, das Sie besitzen oder kontrollieren, oder auf einem";
static unsigned char eula_text_0484[] = "anderen System, auf das der Service von einem Unternehmen der SIE-Gruppe \303\274bertragen wird.";
static unsigned char eula_text_0485[] = "5. Ihr Konto";
static unsigned char eula_text_0486[] = "1. Kontoerstellung: Um bestimmte Spiele und andere Teile des Service nutzen zu k\303\266nnen, m\303\274ssen Sie sich";
static unsigned char eula_text_0487[] = "m\303\266glicherweise f\303\274r ein Konto registrieren. Sie d\303\274rfen nur dann ein Konto erstellen, wenn Sie in Ihrer";
static unsigned char eula_text_0488[] = "Gerichtsbarkeit vollj\303\244hrig sind. Wenn Sie in Ihrer Gerichtsbarkeit noch minderj\303\244hrig sind, muss ein";
static unsigned char eula_text_0489[] = "Elternteil oder Erziehungsberechtigter ein Konto bei uns erstellen, damit Sie auf den Service zugreifen und";
static unsigned char eula_text_0490[] = "ihn nutzen d\303\274rfen.";
static unsigned char eula_text_0491[] = "Sie k\303\266nnen ein Konto erstellen, indem Sie ein Registrierungsformular f\303\274r den Service ausf\303\274llen oder, in";
static unsigned char eula_text_0492[] = "einigen F\303\244llen, Ihr Konto auf einer Plattform eines Drittanbieters mit dem Service verbinden. Sie allein sind";
static unsigned char eula_text_0493[] = "f\303\274r alle Ihre Kontoaktivit\303\244ten verantwortlich und m\303\274ssen selbst f\303\274r die Sicherheit Ihres Passworts sorgen.";
static unsigned char eula_text_0494[] = "Sie verpflichten sich, Ihr Konto und Ihre Ger\303\244te sicher aufzubewahren sowie Aspyr Media unverz\303\274glich \303\274ber";
static unsigned char eula_text_0495[] = "jede Verletzung der Sicherheit oder unbefugte Nutzung Ihres Kontos zu informieren.";
static unsigned char eula_text_0496[] = "2. Fehlerfreie Angaben: Zweck Erstellung Ihres Kontos verpflichten Sie sich, eine g\303\274ltige E-Mail-Adresse und";
static unsigned char eula_text_0497[] = "korrekte Informationen zu Ihrem Konto anzugeben. Sie verpflichten sich au\303\237erdem, diese Informationen auf dem";
static unsigned char eula_text_0498[] = "neuesten Stand zu halten, damit sie jederzeit fehlerfrei sind.";
static unsigned char eula_text_0499[] = "3. Sperrung von Konten: Aspyr Media kann Ihr Konto oder Ihren Zugang zum Service nach eigenem Ermessen";
static unsigned char eula_text_0500[] = "aussetzen, sperren oder k\303\274ndigen, wenn Ihr Verhalten nach Ansicht von Aspyr Media nicht mit diesem Vertrag";
static unsigned char eula_text_0501[] = "\303\274bereinstimmt oder dies aus anderen Gr\303\274nden erforderlich wird.";
static unsigned char eula_text_0502[] = "4. Ihr Benutzername: Aspyr Media kann Sie dazu zwingen, einen Ihrer Bildschirmnamen zu \303\244ndern, wenn (i) es";
static unsigned char eula_text_0503[] = "sich um den Namen einer anderen Person handelt und Sie die Absicht hegen, sich als diese Person auszugeben,";
static unsigned char eula_text_0504[] = "(ii) Sie sich damit die Rechte eines Dritten ohne entsprechende Genehmigung aneignen oder (iii) Aspyr Media";
static unsigned char eula_text_0505[] = "ihn gem\303\244\303\237 allgemeiner Standards f\303\274r inakzeptabel h\303\244lt.";
static unsigned char eula_text_0506[] = "5. Privatsph\303\244re auf Ihrem Konto: Sie erkl\303\244ren sich damit einverstanden, dass Sie im Zusammenhang mit Ihren";
static unsigned char eula_text_0507[] = "Interaktionen mit anderen Nutzern im und durch den Service keine Privatsph\303\244re erwarten k\303\266nnen. Ferner";
static unsigned char eula_text_0508[] = "erkl\303\244ren Sie sich ferner damit einverstanden, dass der Inhalt von Nachrichten oder anderen Mitteilungen, die";
static unsigned char eula_text_0509[] = "von Ihrem Konto aus gesendet werden, sei es in oder durch Chats, Foren, direkte Kommunikation von Benutzer zu";
static unsigned char eula_text_0510[] = "Benutzer oder auf anderen Kan\303\244len, von Aspyr Media nach eigenem Ermessen abgerufen, reproduziert oder";
static unsigned char eula_text_0511[] = "verbreitet werden kann. Bei der \303\234berwachung der Inhalte des Service wird Aspyr Media vollst\303\244ndig mit den";
static unsigned char eula_text_0512[] = "Strafverfolgungsbeh\303\266rden und anderen staatlichen Stellen zusammenarbeiten.";
static unsigned char eula_text_0513[] = "6. Verbot des Kontohandels: Sie d\303\274rfen keine Konten kaufen, verkaufen, verschenken oder tauschen und auch";
static unsigned char eula_text_0514[] = "nicht versuchen, Konten zu kaufen, zu verkaufen, zu verschenken oder zu tauschen. Aspyr Media besitzt oder";
static unsigned char eula_text_0515[] = "hat Lizenzen oder anderweitige Rechte an allen Inhalten, die im Service erscheinen, darunter auch die Konten.";
static unsigned char eula_text_0516[] = "6. Ihre Inhalte und Ihr Verhalten";
static unsigned char eula_text_0517[] = "1. Ihre Inhalte: Jegliche Kommunikation oder Materialien jeglicher Art, die Sie per E-Mail, Post oder auf";
static unsigned char eula_text_0518[] = "anderen Wegen an Aspyr Media oder die \303\226ffentlichkeit im Rahmen oder unter Verwendung des Service \303\274bermitteln,";
static unsigned char eula_text_0519[] = "einschlie\303\237lich Nachrichten, Kommentare, Fotos, Chats, E-Mails, Sprachaufnahmen, Daten, Fragen, Feedbacks oder";
static unsigned char eula_text_0520[] = "Vorschl\303\244ge, werden als Ihre \342\200\236Inhalte\342\200\234 bezeichnet.";
static unsigned char eula_text_0521[] = "Aspyr Media ist nicht der Eigent\303\274mer Ihrer Inhalte. Durch das Einstellen von Inhalten erkl\303\244ren Sie, (i) dass";
static unsigned char eula_text_0522[] = "Sie der Eigent\303\274mer der Inhalte sind oder \303\274ber alle erforderlichen Rechte zur ihrer Ver\303\266ffentlichung und";
static unsigned char eula_text_0523[] = "Weitergabe verf\303\274gen und (ii) dass Sie Aspyr Media die Erlaubniserteilen, Ihre Inhalte zu verwenden,";
static unsigned char eula_text_0524[] = "wiederzuverwenden, zu kopieren, zu adaptieren, zu k\303\274rzen, zu \303\244ndern, zu vertreiben, zu modifizieren, zu";
static unsigned char eula_text_0525[] = "\303\274bersetzen, zu ver\303\266ffentlichen, vorzuf\303\274hren, auszustellen, zu entwickeln, zu reproduzieren, der";
static unsigned char eula_text_0526[] = "\303\226ffentlichkeit mitzuteilen und anderweitig in jeglicher Form und durch jegliche Medien (ob jetzt bekannt oder";
static unsigned char eula_text_0527[] = "in Zukunft entwickelt) auf kommerzieller oder nichtkommerzieller Basis weltweit und dauerhaft zur Verf\303\274gung";
static unsigned char eula_text_0528[] = "zu stellen.";
static unsigned char eula_text_0529[] = "2. Verhaltensrichtlinien: Sie sind f\303\274r Ihr Verhalten als Nutzer des Service verantwortlich. Sie stimmen zu,";
static unsigned char eula_text_0530[] = "dass Sie sich nicht an Handlungen (einschlie\303\237lich der Weitergabe von Inhalten) beteiligen werden, die:";
static unsigned char eula_text_0531[] = "* bedrohlich, schikanierend, verleumderisch, beleidigend, obsz\303\266n, unz\303\274chtig, sexuell provozierend oder";
static unsigned char eula_text_0532[] = "suggestiv oder pornografisch sind oder in irgendeiner Weise eine zivil- oder strafrechtliche Haftung nach";
static unsigned char eula_text_0533[] = "geltendem Recht nach sich ziehen k\303\266nnten;";
static unsigned char eula_text_0534[] = "* als Verunglimpfung, Hassrede oder Angriff auf Einzelpersonen oder Gruppen aufgrund von Rasse, Hautfarbe,";
static unsigned char eula_text_0535[] = "Geschlecht, Alter, Religion, nationaler Herkunft, Behinderung, sexuellen Vorlieben oder Geschlechtsidentit\303\244t";
static unsigned char eula_text_0536[] = "verstanden werden oder werden k\303\266nnten;";
static unsigned char eula_text_0537[] = "* Spam darstellen (das mehrfache Senden derselben Nachricht oder an mehrere Personen oder das mehrfache";
static unsigned char eula_text_0538[] = "Teilen oder Senden desselben Inhalts wird als Spam behandelt);";
static unsigned char eula_text_0539[] = "* eine Aufforderung oder Werbung f\303\274r ein unz\303\274chtiges oder unangemessenes pers\303\266nliches Verhalten, ein";
static unsigned char eula_text_0540[] = "kommerzielles Produkt oder eine Aktivit\303\244t sind;";
static unsigned char eula_text_0541[] = "* zu einem Verhalten ermutigen oder ein Verhalten darstellen, das eine sichere und angenehme Umgebung f\303\274r";
static unsigned char eula_text_0542[] = "alle Nutzer beeintr\303\244chtigt, einschlie\303\237lich, aber nicht beschr\303\244nkt auf Mobbing, Vigilantismus, Verhalten oder";
static unsigned char eula_text_0543[] = "Aktivit\303\244ten, die bedrohlich, sch\303\244dlich, bel\303\244stigend, missbr\303\244uchlich, vulg\303\244r, hasserf\303\274llt, verleumderisch,";
static unsigned char eula_text_0544[] = "unz\303\274chtig, sexuell provozierend, suggestiv oder explizit, aufr\303\274hrerisch, gottesl\303\244sterlich, rassistisch oder";
static unsigned char eula_text_0545[] = "ethnisch anst\303\266\303\237ig oder diskriminierend sind, oder in irgendeiner Weise zu unangemessenem, respektlosem,";
static unsigned char eula_text_0546[] = "beleidigendem oder rechtswidrigem Verhalten ermutigen oder den Service anderweitig zu einer unangenehmen";
static unsigned char eula_text_0547[] = "Erfahrung f\303\274r irgendjemanden machen;";
static unsigned char eula_text_0548[] = "* die Nutzung des Service durch andere Personen einschr\303\244nken oder behindern oder dazu entmutigen;";
static unsigned char eula_text_0549[] = "* darin bestehen, Automatisierungssoftware (Bots) oder andere nicht autorisierte Software von Drittanbietern";
static unsigned char eula_text_0550[] = "zu hacken, zu modifizieren oder anderweitig zu verwenden, die dazu bestimmt ist, das Benutzererlebnis des";
static unsigned char eula_text_0551[] = "Service zu ver\303\244ndern;";
static unsigned char eula_text_0552[] = "* gegen regionale, staatliche, bundesstaatliche oder internationale Gesetze versto\303\237en oder eine";
static unsigned char eula_text_0553[] = "zivilrechtliche Haftung nach sich ziehen;";
static unsigned char eula_text_0554[] = "* gegen Rechte Dritter versto\303\237en oder diese verletzen (einschlie\303\237lich, aber nicht beschr\303\244nkt auf";
static unsigned char eula_text_0555[] = "Urheberrechte, Markenrechte, Rechte auf Privatsph\303\244re oder \303\226ffentlichkeit, Verleumdung oder andere";
static unsigned char eula_text_0556[] = "Eigentumsrechte);";
static unsigned char eula_text_0557[] = "* den Service unangemessen oder unverh\303\244ltnism\303\244\303\237ig stark belasten oder den Service anderweitig beeintr\303\244chtigen;";
static unsigned char eula_text_0558[] = "* einen \342\200\236Kettenbrief\342\200\234 oder eine \342\200\236Junk-Mail\342\200\234 darstellen;";
static unsigned char eula_text_0559[] = "* angeben oder behaupten, dass Sie mit Aspyr Media verbunden sind , wenn Sie es nicht sind, einschlie\303\237lich,";
static unsigned char eula_text_0560[] = "aber nicht beschr\303\244nkt auf Selbstbezeichnungen als \342\200\236Administrator\342\200\234, \342\200\236Moderator\342\200\234 oder ein anderer Mitarbeiter";
static unsigned char eula_text_0561[] = "oder Vertreter von Aspyr Media;";
static unsigned char eula_text_0562[] = "* Anmeldeinformationen von anderen Nutzern abfragen;";
static unsigned char eula_text_0563[] = "* \342\200\236Spoofs\342\200\234 darstellen (Verwendung jeglicher Mittel, um Ihre Online-Identit\303\244t zu verschleiern oder";
static unsigned char eula_text_0564[] = "urspr\303\274ngliche Attributinformationen zu ver\303\244ndern, einschlie\303\237lich, aber nicht beschr\303\244nkt auf doppelte Konten);";
static unsigned char eula_text_0565[] = "* Programme zum \342\200\236Knacken\342\200\234 des Service oder anderer Internet-Sicherheitstools verwenden oder umfassen;";
static unsigned char eula_text_0566[] = "* das Hochladen von Dateien beinhalten, die Viren, trojanische Pferde, W\303\274rmer, besch\303\244digte Dateien oder Daten";
static unsigned char eula_text_0567[] = "oder andere \303\244hnliche Software oder Programme enthalten, die den Betrieb des Service besch\303\244digen oder";
static unsigned char eula_text_0568[] = "behindern k\303\266nnten; oder";
static unsigned char eula_text_0569[] = "* alles andere umfassen, was Aspyr Media nach eigenem Ermessen als beleidigend oder sch\303\244dlich f\303\274r den Service";
static unsigned char eula_text_0570[] = "oder die Integrit\303\244t oder das Gesch\303\244ft vonAspyr Media erachtet.";
static unsigned char eula_text_0571[] = "\342\200\236Mods\342\200\234 sind von Nutzern erstellte Inhalte, die verwendet werden k\303\266nnen, um das Spielerlebnis f\303\274r bestimmte";
static unsigned char eula_text_0572[] = "Spiele und andere Software, aus denen der Service besteht, zu ver\303\244ndern oder zu verbessern. Ihre Erstellung,";
static unsigned char eula_text_0573[] = "Nutzung und \303\234bertragung von Mods unterliegt den Verhaltensregeln in Abschnitt 6.2. Mods m\303\274ssen au\303\237erdem alle";
static unsigned char eula_text_0574[] = "geltenden Nutzungsbedingungen und sonstigen Vereinbarungen von und mit Drittanbietern einhalten.";
static unsigned char eula_text_0575[] = "Aspyr Media beh\303\244lt sich das Recht vor, Mods zu entfernen, die nach eigenem Ermessen (i) gegen diesen Vertrag";
static unsigned char eula_text_0576[] = "oder geltendes Recht versto\303\237en oder (ii) beleidigend, unangemessen oder anderweitig zu beanstanden sind.";
static unsigned char eula_text_0577[] = "Durch die \303\234bermittlung von Mods an Aspyr Media gew\303\244hren Sie Aspyr Media eine weltweite, nicht-exklusive,";
static unsigned char eula_text_0578[] = "geb\303\274hrenfreie, voll bezahlte, unterlizenzierbare und \303\274bertragbare Lizenz zur weltweiten und dauerhaften";
static unsigned char eula_text_0579[] = "Nutzung, Reproduktion, Verteilung, Erstellung von abgeleiteten Werken, \303\266ffentlichen Auff\303\274hrung, \303\266ffentlichen";
static unsigned char eula_text_0580[] = "Darstellung, digitalen Auff\303\274hrung, Herstellung, Herstellung durch Dritte, zum Verkauf, zur Erstellung von";
static unsigned char eula_text_0581[] = "Verkaufsangeboten und zum Import Ihrer Mods, ganz oder teilweise, f\303\274r jeden Zweck und in jeder Form, jedem";
static unsigned char eula_text_0582[] = "Medium oder jeder Technologie, die jetzt bekannt sind oder in Zukunft entwickelt werden. Au\303\237erdem erkl\303\244ren";
static unsigned char eula_text_0583[] = "Sie sich damit einverstanden, dass Sie hiermit auf alle moralischen Rechte der Urheberschaft, der";
static unsigned char eula_text_0584[] = "Ver\303\266ffentlichung, des Rufs oder der Zuschreibung bez\303\274glich der Verwendung dieser Mods durch Aspyr Media oder";
static unsigned char eula_text_0585[] = "andere Spieler verzichten.";
static unsigned char eula_text_0586[] = "F\303\274r einige Spiele, die Teil des Service sind, verwendet Aspyr Media zur Verwaltung von Mods die Plattform";
static unsigned char eula_text_0587[] = "\342\200\236Mod.io\342\200\234. Um auf Mods zuzugreifen oder sie verf\303\274gbar zu machen, m\303\274ssen Sie sich f\303\274r ein Mod.io-Konto";
static unsigned char eula_text_0588[] = "registrieren. Ihr Mod.io-Konto und Ihre Nutzung der Dienste von Mod.io unterliegen Ihrer Annahme und";
static unsigned char eula_text_0589[] = "Einhaltung der Bedingungen der Endnutzer-Lizenzvereinbarung und der Datenschutzrichtlinie von Mod.io. Auf";
static unsigned char eula_text_0590[] = "https://mod.io/members/privacy k\303\266nnen Sie Ihr Konto und Ihre Datenschutzeinstellungen verwalten und Ihre";
static unsigned char eula_text_0591[] = "pers\303\266nlichen Daten jederzeit l\303\266schen oder \303\244ndern.";
static unsigned char eula_text_0592[] = "Wenn Sie ein Urheberrechtsinhaber oder dessen Vertreter sowie der Meinung sind, dass Inhalte eines Mods Ihre";
static unsigned char eula_text_0593[] = "Urheberrechte verletzen, k\303\266nnen Sie uns dies \303\274ber Mod.io oder mittels einer Nachricht an unseren";
static unsigned char eula_text_0594[] = "Urheberrechtsvertreter unter den Kontaktinformationen in Abschnitt 15 mitteilen.";
static unsigned char eula_text_0595[] = "8. Virtuelle Gegenst\303\244nde";
static unsigned char eula_text_0596[] = "Virtuelle Gegenst\303\244nde, Kost\303\274me, herunterladbare Inhalte und virtuelle \342\200\236Token\342\200\234 oder W\303\244hrungen (zusammenfassend";
static unsigned char eula_text_0597[] = "\342\200\236virtuelle Gegenst\303\244nde\342\200\234) k\303\266nnen zum Kauf angeboten oder anderweitig \303\274ber den Service verdient oder erworben";
static unsigned char eula_text_0598[] = "werden. Ihre Entscheidung, einen Kauf mit Echtgeld zu t\303\244tigen, stellt ein Angebot an Aspyr Media dar, zu den";
static unsigned char eula_text_0599[] = "Preisen und Bedingungen zu kaufen, die im Service angegeben sind.";
static unsigned char eula_text_0600[] = "Sie erkl\303\244ren sich damit einverstanden, dass Sie keine Rechte oder Anspr\303\274che an virtuellen Gegenst\303\244nden haben.";
static unsigned char eula_text_0601[] = "Aspyr Media erkennt keine angeblichen \303\234bertragungen von virtuellen Gegenst\303\244nden au\303\237erhalb des Service oder";
static unsigned char eula_text_0602[] = "den angeblichen Verkauf, das Verschenken oder den Handel in der \342\200\236realen Welt\342\200\234 von irgendetwas an, das im";
static unsigned char eula_text_0603[] = "Service erscheint oder von ihm stammt. Es ist Ihnen nicht gestattet, virtuelle Gegenst\303\244nde gegen \342\200\236echtes\342\200\234";
static unsigned char eula_text_0604[] = "Geld zu verkaufen oder sie gegen einen Wert au\303\237erhalb des Service einzutauschen oder auf andere Weise";
static unsigned char eula_text_0605[] = "virtuelle Gegenst\303\244nde ohne die ausdr\303\274ckliche schriftliche Genehmigung von Aspyr Media zu verkaufen oder zu";
static unsigned char eula_text_0606[] = "tauschen oder anderweitig damit zu handeln. Zur weiteren Verdeutlichung sei hiermit betont, dass virtuelle";
static unsigned char eula_text_0607[] = "Gegenst\303\244nde keinen realen Wert haben, sind lizenziert sind und kein Eigentum darstellen. Unter keinen";
static unsigned char eula_text_0608[] = "Umst\303\244nden erhalten Sie Eigentums- oder sonstige Schutzrechte an den virtuellen Gegenst\303\244nden.";
static unsigned char eula_text_0609[] = "Sofern nicht gesetzlich vorgeschrieben oder anderweitig im Service oder auf der Drittplattform, \303\274ber die Sie";
static unsigned char eula_text_0610[] = "auf den Service zugreifen, angegeben, sind alle Verk\303\244ufe von virtuellen Gegenst\303\244nden endg\303\274ltig, sobald die";
static unsigned char eula_text_0611[] = "Transaktion verarbeitet wurde, und es werden keine R\303\274ckerstattungen gew\303\244hrt.";
static unsigned char eula_text_0612[] = "9. Supportleistungen";
static unsigned char eula_text_0613[] = "Aspyr Media kann Ihnen nach eigenem Ermessen Kunden- und technische Unterst\303\274tzungsdienste im Zusammenhang mit";
static unsigned char eula_text_0614[] = "dem Service zur Verf\303\274gung stellen (\342\200\236Supportleistungen\342\200\234). Aspyr Media ist nicht verpflichtet,";
static unsigned char eula_text_0615[] = "Supportleistungen zu erbringen, es sei denn, dies ist durch geltendes Recht vorgeschrieben. Das Vers\303\244umnis,";
static unsigned char eula_text_0616[] = "Supportleistungen zu erbringen oder deren Erbringung fortzusetzen, stellt keinen Versto\303\237 von Aspyr Media";
static unsigned char eula_text_0617[] = "gegen diesen Vertrag dar. Jeder zus\303\244tzliche Software-Code, der Ihnen als Teil der Supportleistungen zur";
static unsigned char eula_text_0618[] = "Verf\303\274gung gestellt wird, gilt als Teil des Service, ist und bleibt im Verh\303\244ltnis zwischen Ihnen und Aspyr";
static unsigned char eula_text_0619[] = "Media das alleinige Eigentum von Aspyr Media und unterliegt den Bedingungen und Bestimmungen dieses Vertrags.";
static unsigned char eula_text_0620[] = "Sie erreichen den Support von Aspyr Media auf https://support.aspyr.com/hc/en-us. Keine der Plattformen von";
static unsigned char eula_text_0621[] = "Drittanbietern oder deren Eigent\303\274mer sind unter irgendwelchen Umst\303\244nden verpflichtet, Supportleistungen in";
static unsigned char eula_text_0622[] = "Bezug auf den Service zu erbringen. Sie erkl\303\244ren sich damit einverstanden, dass Sie sich im Zusammenhang mit";
static unsigned char eula_text_0623[] = "Supportleistungen ausschlie\303\237lich an Aspyr Media wenden werden.";
static unsigned char eula_text_0624[] = "10. Laufzeit und K\303\274ndigung";
static unsigned char eula_text_0625[] = "Die Laufzeit dieses Vertrags beginnt mit dem Herunterladen oder der ersten Nutzung des Service und gilt so";
static unsigned char eula_text_0626[] = "lange, wie Sie Kopien des Service in Ihrem Besitz haben oder auf den Service zugreifen.";
static unsigned char eula_text_0627[] = "Unbeschadet sonstiger Rechte kann Aspyr Media diesen Vertrag jederzeit und aus beliebigem Grund einseitig";
static unsigned char eula_text_0628[] = "k\303\274ndigen oder \303\244ndern, ohne Sie davon in Kenntnis zu setzen. Beispielsweise kann Aspyr Media diesen Vertrag";
static unsigned char eula_text_0629[] = "und Ihre Rechte in Verbindung mit dem Service k\303\274ndigen, wenn Aspyr Media nach eigenem Ermessen den Service";
static unsigned char eula_text_0630[] = "oder einen Teil des Service einstellt, die Unterst\303\274tzung oder Wartung des Service oder eines Teils des";
static unsigned char eula_text_0631[] = "Service beendet, keine Updates mehr bereitstellt, den Service nicht mehr zur Lizenzierung anbietet oder";
static unsigned char eula_text_0632[] = "glaubt, dass Sie diesen Vertrag nicht eingehalten haben.";
static unsigned char eula_text_0633[] = "Wenn Aspyr Media diesen Vertrag aufgrund Ihrer Nichteinhaltung seiner Bestimmungen oder Bedingungen k\303\274ndigt,";
static unsigned char eula_text_0634[] = "(i) werden keine R\303\274ckerstattungen vorgenommen und (ii) m\303\274ssen Sie unverz\303\274glich alle in Ihrem Besitz";
static unsigned char eula_text_0635[] = "befindlichen Kopien des Service zerst\303\266ren oder l\303\266schen. Wenn die \303\204nderung dieses Vertrags durch Aspyr Media";
static unsigned char eula_text_0636[] = "Ihre Rechte in Verbindung mit dem Service wesentlich beeintr\303\244chtigt, was Aspyr Media nach eigenem Ermessen";
static unsigned char eula_text_0637[] = "beurteilt, kann Aspyr Media Sie per E-Mail an Ihre zuletzt bekannte E-Mail-Adresse benachrichtigen, ist aber";
static unsigned char eula_text_0638[] = "nicht dazu verpflichtet. Aspyr Media \303\274bernimmt keine Haftung, wenn Sie eine solche Benachrichtigung nicht";
static unsigned char eula_text_0639[] = "erhalten.";
static unsigned char eula_text_0640[] = "Aspyr Media beh\303\244lt sich das Recht vor, den Service (oder Teile des Service) jederzeit mit oder ohne";
static unsigned char eula_text_0641[] = "Vorank\303\274ndigung vor\303\274bergehend oder dauerhaft zu \303\244ndern oder einzustellen. Sie erkl\303\244ren sich damit";
static unsigned char eula_text_0642[] = "einverstanden, dass Aspyr Media Ihnen oder Dritten gegen\303\274ber nicht f\303\274r \303\204nderungen, Aussetzungen oder";
static unsigned char eula_text_0643[] = "Unterbrechungen des Service haftbar ist.";
static unsigned char eula_text_0644[] = "11. \303\234berwachung";
static unsigned char eula_text_0645[] = "Aspyr Media beh\303\244lt sich das Recht vor, die Nutzung des Service zu \303\274berwachen, um die Einhaltung dieses";
static unsigned char eula_text_0646[] = "Vertrags zu gew\303\244hrleisten, sowie das Recht, Inhalte, Informationen oder Materialien ganz oder teilweise nach";
static unsigned char eula_text_0647[] = "eigenem Ermessen zu bearbeiten, deren Ver\303\266ffentlichung zu verweigern oder sie zu entfernen. Wir behalten uns";
static unsigned char eula_text_0648[] = "das Recht vor, jeder Person den Zugang zum Service jederzeit und aus jedem Grund zu verweigern.";
static unsigned char eula_text_0649[] = "Aspyr Media kann Ihre Inhalte und andere Kommunikationen \303\274berwachen, um die Qualit\303\244t des von Ihnen erhaltenen";
static unsigned char eula_text_0650[] = "Service, Ihre Einhaltung des Vertrags oder die Sicherheit des Service zu bewerten oder aus anderen Gr\303\274nden.";
static unsigned char eula_text_0651[] = "Sie erkl\303\244ren sich damit einverstanden, dass solche \303\234berwachungsaktivit\303\244ten Sie nicht zu einem Klagegrund oder";
static unsigned char eula_text_0652[] = "einem anderen Recht in Bezug auf die Art und Weise berechtigen, in der Aspyr Media oder seine verbundenen";
static unsigned char eula_text_0653[] = "Unternehmen oder Vertreter Ihre Inhalte und andere Kommunikation \303\274berwachen und die Bestimmungen des Vertrags";
static unsigned char eula_text_0654[] = "durchsetzen oder nicht durchsetzen. In keinem Fall sind Aspyr Media oder eine seiner Tochtergesellschaften";
static unsigned char eula_text_0655[] = "oder Vertreter haftbar f\303\274r Kosten, Sch\303\244den, Ausgaben oder andere Verbindlichkeiten, die Ihnen als Folge von";
static unsigned char eula_text_0656[] = "\303\234berwachungsaktivit\303\244ten durch Aspyr Media oder seine Tochtergesellschaften oder Vertreter entstehen.";
static unsigned char eula_text_0657[] = "12. Sicherheit der Daten\303\274bertragung und -speicherung";
static unsigned char eula_text_0658[] = "Die elektronische Kommunikation \303\274ber den Service ist m\303\266glicherweise nicht immer verschl\303\274sselt. Sie erkennen";
static unsigned char eula_text_0659[] = "das bestehende Risiko an, dass Daten, einschlie\303\237lich E-Mail, elektronischer Kommunikation und pers\303\266nlicher";
static unsigned char eula_text_0660[] = "Daten, von unbefugten Dritten eingesehen werden k\303\266nnen, wenn sie zwischen Ihnen und Aspyr Media oder zwischen";
static unsigned char eula_text_0661[] = "Ihnen und anderen Parteien \303\274bermittelt werden. Au\303\237erdem k\303\266nnen Ihre Mitteilungen und Inhalte im Service f\303\274r";
static unsigned char eula_text_0662[] = "andere \303\266ffentlich zug\303\244nglich sein.";
static unsigned char eula_text_0663[] = "Aspyr Media und seine verbundenen Unternehmen und Vertreter sind berechtigt, aber nicht verpflichtet, Ihre";
static unsigned char eula_text_0664[] = "Inhalte und andere Mitteilungen zu \303\274berpr\303\274fen oder aufzubewahren.";
static unsigned char eula_text_0665[] = "Der Service kann Links zu anderen Websites und Softwareanwendungen enthalten, auch in Form von Werbeanzeigen";
static unsigned char eula_text_0666[] = "(die \342\200\236verlinkten Dienste\342\200\234). Aspyr Media hat keine Kontrolle \303\274ber die verlinkten Dienste, und Aspyr Media";
static unsigned char eula_text_0667[] = "sowie seine verbundenen Unternehmen und Vertreter geben keinerlei Zusicherungen bez\303\274glich des Inhalts, der";
static unsigned char eula_text_0668[] = "Genauigkeit, der Sicherheit oder des Datenschutzes dieser verlinkten Dienste. Die Tatsache, dass Aspyr Media";
static unsigned char eula_text_0669[] = "einen Link zu einer externen Website bereitstellt, bedeutet keine Bef\303\274rwortung, Genehmigung, F\303\266rderung oder";
static unsigned char eula_text_0670[] = "Zugeh\303\266rigkeit in Bezug auf solche verlinkten Dienste, ihre Eigent\303\274mer oder ihre Anbieter. Die Verwendung von";
static unsigned char eula_text_0671[] = "Informationen, Software oder Produkten, die \303\274ber das Internet verf\303\274gbar sind, bringt Risiken mit sich. Aspyr";
static unsigned char eula_text_0672[] = "Media weist Sie darauf hin, dass Sie sich \303\274ber diese Risiken im Klaren sein sollten, bevor Sie irgendwelche";
static unsigned char eula_text_0673[] = "Inhalte \303\274ber das Internet abrufen, verwenden, kaufen oder sich darauf verlassen. Sie erkl\303\244ren sich damit";
static unsigned char eula_text_0674[] = "einverstanden, dass Sie Aspyr Media oder seine verbundenen Unternehmen oder Vertreter unter keinen Umst\303\244nden";
static unsigned char eula_text_0675[] = "f\303\274r Verluste oder Sch\303\244den haftbar machen, die durch Ihre Nutzung von oder Ihr Vertrauen auf Inhalte, Waren";
static unsigned char eula_text_0676[] = "oder Dienstleistungen entstehen, die \303\274ber die verlinkten Dienste verf\303\274gbar sind.";
static unsigned char eula_text_0677[] = "14. Warenzeichen und Urheberrechte";
static unsigned char eula_text_0678[] = "Der Service ist Eigentum von Aspyr Media und durch US-amerikanische und internationale Urheberrechtsgesetze";
static unsigned char eula_text_0679[] = "und andere Gesetze zum Schutz geistigen Eigentums sowie durch vertragliche Bestimmungen gesch\303\274tzt. Alle";
static unsigned char eula_text_0680[] = "Serviceinhalte, Warenzeichen, Dienstleistungsmarken, Handelsnamen, Logos und Symbole sind Eigentum von Aspyr";
static unsigned char eula_text_0681[] = "Media oder werden von Aspyr Media unter Lizenz verwendet. Keinerlei Inhalte oder Merkmale des Service sind so";
static unsigned char eula_text_0682[] = "zu verstehen, dass eine Lizenz oder ein Recht zur Nutzung einer in im Service dargestellten Marke ohne die";
static unsigned char eula_text_0683[] = "schriftliche Genehmigung von Aspyr Media oder eines Dritten, der Eigent\303\274mer der im Service dargestellten";
static unsigned char eula_text_0684[] = "Warenzeichen sein kann, gew\303\244hrt wird. Die Verwendung der im Service dargestellten Marken oder sonstiger";
static unsigned char eula_text_0685[] = "Inhalte des Service ist strengstens untersagt, es sei denn, sie ist in diesem Vertrag vorgesehen.";
static unsigned char eula_text_0686[] = "Geistiges Eigentum, das \303\274ber den Service angezeigt wird, ist entweder das Eigentum von Aspyr Media oder wird";
static unsigned char eula_text_0687[] = "mit Genehmigung seines Inhabers von Aspyr Media verwendet. Es ist Ihnen untersagt, dieses geistige Eigentum";
static unsigned char eula_text_0688[] = "zu nutzen oder seine Nutzung zu genehmigen, es sei denn, dies ist im Rahmen dieses Vertrags ausdr\303\274cklich";
static unsigned char eula_text_0689[] = "gestattet. Jede unbefugte Nutzung dieses geistigen Eigentums kann gegen Urheberrechtsgesetze, Markengesetze,";
static unsigned char eula_text_0690[] = "Gesetze zum Schutz der Privatsph\303\244re und der \303\226ffentlichkeit sowie gegen andere Vorschriften und Gesetze";
static unsigned char eula_text_0691[] = "versto\303\237en.";
static unsigned char eula_text_0692[] = "15. Beschwerden bez\303\274glich des Urheberrechts";
static unsigned char eula_text_0693[] = "Wenn Sie ein Urheberrechtsinhaber oder dessen Vertreter sind und glauben, dass Inhalte des Service Ihre";
static unsigned char eula_text_0694[] = "Urheberrechte verletzen, k\303\266nnen Sie anhand der unten aufgef\303\274hrten Informationen eine DMCA-Meldung schriftlich";
static unsigned char eula_text_0695[] = "an unseren Urheberrechtsbeauftragten senden (gem\303\244\303\237 dem US-amerikanischen Digital Millennium Copyright Act).";
static unsigned char eula_text_0696[] = "Wenn wir eine Benachrichtigung \303\274ber eine mutma\303\237liche Urheberrechtsverletzung erhalten, werden wir nach";
static unsigned char eula_text_0697[] = "eigenem Ermessen alle Ma\303\237nahmen ergreifen, die wir f\303\274r angemessen halten, einschlie\303\237lich der Entfernung der";
static unsigned char eula_text_0698[] = "mutma\303\237lich verletzenden Materialien aus dem Service oder der Sperrung des \303\266ffentlichen Zugangs zu ihnen.";
static unsigned char eula_text_0699[] = "Dar\303\274ber hinaus k\303\266nnen wir bei wiederholten Verst\303\266\303\237en in Bezug auf urheberrechtlich gesch\303\274tzte Inhalte den";
static unsigned char eula_text_0700[] = "Zugang zuwiderhandelnder Personen zum Service sperren, ihre Inhalte entfernen und ihr Konto schlie\303\237en.";
static unsigned char eula_text_0701[] = "* eine physische oder elektronische Unterschrift einer Person, die befugt ist, im Namen des Inhabers eines";
static unsigned char eula_text_0702[] = "exklusiven Rechts zu handeln, das angeblich verletzt wurde;";
static unsigned char eula_text_0703[] = "* Identifizierung des urheberrechtlich gesch\303\274tzten Werks, das angeblich verletzt wurde, oder, wenn mehrere";
static unsigned char eula_text_0704[] = "urheberrechtlich gesch\303\274tzte Werke beansprucht werden, eine Liste dieser Werke im Service;";
static unsigned char eula_text_0705[] = "* Identifizierung des Materials, das angeblich gegen die Bestimmungen verst\303\266\303\237t und deaktiviert werden soll,";
static unsigned char eula_text_0706[] = "in einer Weise, die es uns erm\303\266glicht, das Material zu lokalisieren;";
static unsigned char eula_text_0707[] = "* Informationen, die ausreichen, um mit Ihnen in Kontakt treten zu k\303\266nnen, wie beispielsweise Ihre";
static unsigned char eula_text_0708[] = "E-Mail-Adresse, Anschrift oder Telefonnummer;";
static unsigned char eula_text_0709[] = "* eine Erkl\303\244rung, dass Sie in gutem Glauben davon ausgehen, dass die Verwendung des Materials in der";
static unsigned char eula_text_0710[] = "beanstandeten Weise nicht vom Urheberrechtsinhaber, seinem Vertreter oder dem Gesetz genehmigt ist; und";
static unsigned char eula_text_0711[] = "* eine Erkl\303\244rung mit dem Inhalt, dass die Informationen in Ihrer Meldung den Tatsachen entsprechen und der";
static unsigned char eula_text_0712[] = "Beschwerdef\303\274hrer an Eides statt versichert, im Namen des Inhabers eines exklusiven, mutma\303\237lich verletzten";
static unsigned char eula_text_0713[] = "Rechtes aufzutreten.";
static unsigned char eula_text_0714[] = "Unser Urheberrechtsbeauftragter ist unter der folgenden Anschrift oder E-Mail-Adresse zu erreichen:";
static unsigned char eula_text_0715[] = "1250 S Capital of Texas Hwy, Floor 6, Austin, TX 78746, USA";
static unsigned char eula_text_0716[] = "legal@aspyr.com";
static unsigned char eula_text_0717[] = "16. Ausschluss von Garantien";
static unsigned char eula_text_0718[] = "Ihre Nutzung des Service erfolgt vollst\303\244ndig auf eigene Gefahr.";
static unsigned char eula_text_0719[] = "Der Service wird von Aspyr Media \342\200\236wie besehen\342\200\234 bereitgestellt. Aspyr Media lehnt ausdr\303\274cklich alle Garantien";
