static unsigned char eula_text_0721[] = "stillschweigenden Garantien der Marktg\303\244ngigkeit, der Eignung f\303\274r einen bestimmten Zweck und der";
static unsigned char eula_text_0722[] = "Nichtverletzung von Rechten Dritter.";
static unsigned char eula_text_0723[] = "Aspyr Media \303\274bernimmt keine Garantie daf\303\274r, dass (i) der Service Ihren Anforderungen entspricht, (ii) dass";
