static unsigned char eula_text_0725[] = "Ergebnisse, die durch die Nutzung des Service erzielt werden k\303\266nnen, genau oder zuverl\303\244ssig sein werden.";
static unsigned char eula_text_0726[] = "Keinerlei Ratschl\303\244ge oder Informationen, die Sie in m\303\274ndlicher oder schriftlicher Form von Aspyr Media oder";
static unsigned char eula_text_0727[] = "\303\274ber den Service erhalten haben, begr\303\274nden eine Garantie in Bezug auf den Service, die nicht ausdr\303\274cklich in";
static unsigned char eula_text_0728[] = "diesem Vertrag angegeben ist.";
