static unsigned char eula_text_0730[] = "ein Teil des Service die Unreal Engine bzw. die Unity Engine verwendet) ist eine Partei dieses Vertrags oder";
static unsigned char eula_text_0731[] = "Ihres Kaufs des Service oder Ihrer Lizenz daf\303\274r. Weder die Drittplattformen noch Epic oder Unity geben oder";
static unsigned char eula_text_0732[] = "\303\274bernehmen Garantien oder andere Verpflichtungen in Bezug auf (i) den Service oder (ii) Anspr\303\274che, Verluste,";
static unsigned char eula_text_0733[] = "Haftungen, Sch\303\244den, Kosten oder Ausgaben, die dem Service zuzuschreiben sind, einschlie\303\237lich Garantien, die";
static unsigned char eula_text_0734[] = "sich aus Anspr\303\274chen wegen der Verletzung von Rechten an geistigem Eigentum oder pers\303\266nlichen Rechten, der";
static unsigned char eula_text_0735[] = "Produkthaftung oder der Nichterf\303\274llung, Ausf\303\274hrung oder Konformit\303\244t des Service mit einem Standard ergeben.";
static unsigned char eula_text_0736[] = "Da in einigen Staaten oder Gerichtsbarkeiten der Ausschluss stillschweigender Garantien nicht zul\303\244ssig ist,";
static unsigned char eula_text_0737[] = "gilt der vorstehende Garantieausschluss m\303\266glicherweise nicht f\303\274r Sie.";
static unsigned char eula_text_0738[] = "17. Haftungsbeschr\303\244nkung";
