static unsigned char eula_text_0740[] = "Drittplattform, Epic oder Unity f\303\274r direkte, indirekte, zuf\303\244llige, besondere, Folge- oder exemplarische";
static unsigned char eula_text_0741[] = "Sch\303\244den haftet, einschlie\303\237lich Sch\303\244den aus entgangenem Gewinn, Firmenwert, entgangener Nutzung, entgangenen";
static unsigned char eula_text_0742[] = "Waren oder Daten oder anderen immateriellen Verlusten (selbst wenn Aspyr Media, die Drittplattform, Epic oder";
