static unsigned char eula_text_0745[] = "Sie verzichten hiermit ausdr\303\274cklich und unwiderruflich auf die Geltendmachung von Anspr\303\274chen gegen";
static unsigned char eula_text_0746[] = "Drittplattformen, Epic oder Unity, die Sie m\303\266glicherweise nach dem Gesetz oder dem Billigkeitsrecht irgendwo";
static unsigned char eula_text_0747[] = "auf der Welt im Zusammenhang mit den unter diesem Vertrag lizenzierten Rechten, Ihrem Besitz oder Ihrer";
static unsigned char eula_text_0748[] = "Nutzung des Service oder dem Inhalt des Service haben k\303\266nnten. Jegliche Anspr\303\274che, die sich aus dem Service";
static unsigned char eula_text_0749[] = "ergeben, unterliegen den in diesem Vertrag dargelegten Einschr\303\244nkungen und k\303\266nnen ausschlie\303\237lich gem\303\244\303\237 den";
static unsigned char eula_text_0750[] = "Bestimmungen der Abschnitte 23 und 24 unten gegen Aspyr Media geltend gemacht werden.";
static unsigned char eula_text_0751[] = "Da einige Staaten oder Gerichtsbarkeiten den Ausschluss oder die Beschr\303\244nkung der Haftung f\303\274r Folgesch\303\244den";
static unsigned char eula_text_0752[] = "nicht gestatten, ist in solchen Staaten oder Gerichtsbarkeiten unsere Haftung auf den maximalen gesetzlich";
static unsigned char eula_text_0753[] = "zul\303\244ssigen Umfang beschr\303\244nkt.";
static unsigned char eula_text_0754[] = "18. Schadloshaltung";
static unsigned char eula_text_0755[] = "Sie erkl\303\244ren sich damit einverstanden, Aspyr Media und seine verbundenen Unternehmen sowie deren jeweilige";
static unsigned char eula_text_0756[] = "Gesch\303\244ftsleitung, leitende Angestellte, Vertreter und Mitarbeiter von allen Anspr\303\274chen, Forderungen,";
static unsigned char eula_text_0757[] = "Verlusten, Kosten oder Ausgaben, einschlie\303\237lich Anwaltshonoraren, freizustellen und schadlos zu halten, die";
static unsigned char eula_text_0758[] = "von einer nat\303\274rlichen oder juristischen Person geltend gemacht werden, die sich aus Ihrer Verletzung dieses";
static unsigned char eula_text_0759[] = "Vertrags, staatlicher oder US-bundesstaatlicher Gesetze oder Vorschriften oder der Rechte einer anderen";
static unsigned char eula_text_0760[] = "Person ergeben, einschlie\303\237lich der Verletzung von Urheberrechten, Eigentumsrechten und Datenschutzrechten.";
static unsigned char eula_text_0761[] = "Unter keinen Umst\303\244nden, auch nicht bei Fahrl\303\244ssigkeit, haften Aspyr Media, seine Tochtergesellschaften oder";
static unsigned char eula_text_0762[] = "deren jeweilige Vertreter und Mitarbeiter f\303\274r Sch\303\244den jeglicher Art, die sich aus der Nutzung oder der";
static unsigned char eula_text_0763[] = "Unm\303\266glichkeit der Nutzung des Service ergeben.";
static unsigned char eula_text_0764[] = "19. Ihre personenbezogenen Daten";
static unsigned char eula_text_0765[] = "Bestimmte pers\303\266nliche und andere Informationen, die wir sammeln, verarbeiten und weitergeben, unterliegen";
static unsigned char eula_text_0766[] = "unserer Datenschutzrichtlinie.  Als Bedingung f\303\274r die Nutzung des Service erkl\303\244ren Sie sich mit den";
static unsigned char eula_text_0767[] = "Bestimmungen unserer Datenschutzrichtlinie einverstanden, die von Zeit zu Zeit ge\303\244ndert werden kann. Unsere";
static unsigned char eula_text_0768[] = "Datenschutzrichtlinie, auf die wir hiermit verweisen, finden Sie unter https://www.aspyr.com/privacy. Sie";
static unsigned char eula_text_0769[] = "erkl\303\244ren sich damit einverstanden, dass Ihre Nutzung des Service unserer Datenschutzrichtlinie unterliegt.";
static unsigned char eula_text_0770[] = "20. Drittbeg\303\274nstigte";
static unsigned char eula_text_0771[] = "Sie erkennen an und erkl\303\244ren sich damit einverstanden, dass die Drittplattformen, Drittanbieter, Epic und";
static unsigned char eula_text_0772[] = "Unity Drittbeg\303\274nstigte dieses Vertrags sind und dass nach Ihrer Zustimmung zu den Bedingungen und";
static unsigned char eula_text_0773[] = "Bestimmungen dieses Vertrags jede der vorgenannten Drittparteien das Recht hat (wobei davon ausgegangen wird,";
static unsigned char eula_text_0774[] = "dass sie das Recht akzeptiert hat), diesen Vertrag als Drittbeg\303\274nstigter durchzusetzen.";
static unsigned char eula_text_0775[] = "21. Gesetzlich vorgeschriebene Offenlegungen";
