static unsigned char eula_text_0838[] = "Geb\303\274hren werden gem\303\244\303\237 den JAMS-Regeln aufgeteilt. Das Schiedsverfahren findet in Austin, Texas, USA, statt,";
static unsigned char eula_text_0839[] = "au\303\237er wenn sich die Parteien auf Video-, Telefon- oder Internetkonferenzen einigen.";
