static unsigned char eula_text_1293[] = "individuellement.";
static unsigned char eula_text_1294[] = "ASPYR MEDIA ET VOUS CONVENEZ QUE (i) IL N\342\200\231Y A AUCUN DROIT OU AUTORIT\303\211 POUR";
