static unsigned char eula_text_1299[] = "La loi f\303\251d\303\251rale sur l\342\200\231arbitrage et la l\303\251gislation f\303\251d\303\251rale sur l'arbitrage s\342\200\231appliquent au pr\303\251sent contrat et";
