static unsigned char eula_text_1308[] = "r\303\250gles et proc\303\251dures d\342\200\231arbitrage simplifi\303\251es. Vous pouvez consulter ces r\303\250gles sur le site jamsadr.com ou en";
static unsigned char eula_text_1309[] = "appelant le 800-352-5267. Le paiement des frais de d\303\251p\303\264t initiaux sera effectu\303\251 par la partie qui d\303\251pose la";
static unsigned char eula_text_1310[] = "plainte, et tous les autres frais de d\303\251p\303\264t et autres frais seront r\303\251partis conform\303\251ment aux r\303\250gles de JAMS.";
