static unsigned char eula_text_1384[] = "conformit\303\240 ai termini e alle condizioni del presente Contratto, cos\303\254 come potr\303\240 essere modificato da Aspyr";
static unsigned char eula_text_1385[] = "Media di volta in volta; e";
static unsigned char eula_text_1386[] = "3. L\342\200\231utente comprende e accetta il presente Contratto, che ha ricevuto, nonch\303\251 i relativi termini e";
static unsigned char eula_text_1387[] = "condizioni, e riconosce e dimostra di potervi accedere.";
