static unsigned char eula_text_1389[] = "pubblicando la versione pi\303\271 recente del Contratto sul nostro sito web con una nuova Data di entrata in";
static unsigned char eula_text_1390[] = "vigore. Tutte le modifiche apportate al Contratto saranno efficaci a partire dalla Data di entrata in vigore.";
static unsigned char eula_text_1391[] = "Se l\342\200\231utente continua ad utilizzare il Servizio dopo la pubblicazione di eventuali modifiche al presente";
static unsigned char eula_text_1392[] = "Contratto, ci\303\262 implicher\303\240 l\342\200\231accettazione di tali modifiche. Qualora non si accettino i termini e le";
static unsigned char eula_text_1393[] = "condizioni del presente Contratto, si prega di interrompere l\342\200\231utilizzo del Servizio.";
static unsigned char eula_text_1394[] = "2. Licenza di Aspyr Media per l\342\200\231utente";
