static unsigned char eula_text_1397[] = "parte dell\342\200\231utente dei termini e delle condizioni del presente Contratto. L\342\200\231utente non pu\303\262 affittare,";
static unsigned char eula_text_1398[] = "noleggiare, prestare, vendere, trasferire, ridistribuire o concedere a sua volta in licenza il Servizio e, se";
static unsigned char eula_text_1399[] = "intende vendere o trasferire in altro modo un dispositivo su cui \303\250 installata una qualsiasi parte del";
