static unsigned char eula_text_1402[] = "modificare o creare opere derivate dal Servizio, da qualsiasi aggiornamento o da qualsiasi parte di esso (ad";
static unsigned char eula_text_1403[] = "eccezione e solo nella misura in cui qualsiasi restrizione di cui sopra sia vietata dalla legge applicabile o";
