static unsigned char eula_text_1427[] = "Contratto e nessuna Societ\303\240 del Gruppo SIE ha alcun obbligo nei confronti dell\342\200\231utente in relazione al";
static unsigned char eula_text_1428[] = "Servizio. Il presente Contratto \303\250 stipulato tra Aspyr Media e l\342\200\231utente, non tra le Societ\303\240 del Gruppo SIE e";
