static unsigned char eula_text_1436[] = "5. L\342\200\231account utente";
static unsigned char eula_text_1437[] = "1. Creazione dell\342\200\231account. Potrebbe essere necessario registrare un Account per utilizzare alcuni giochi e";
static unsigned char eula_text_1438[] = "altre parti del Servizio. \303\210 possibile creare un Account solo se non si \303\250 minorenni nella propria";
