static unsigned char eula_text_1440[] = "creare un Account con noi per poter accedere e utilizzare il Servizio.";
static unsigned char eula_text_1441[] = "L\342\200\231utente pu\303\262 creare un Account iscrivendosi tramite un modulo di registrazione sul Servizio o, in alcuni";
static unsigned char eula_text_1442[] = "casi, collegando al Servizio il proprio account da una Piattaforma di terze parti. L\342\200\231utente \303\250 l\342\200\231unico";
