static unsigned char eula_text_1444[] = "propri dispositivi al sicuro e di notificare a Aspyr Media immediatamente qualsiasi violazione della";
static unsigned char eula_text_1445[] = "sicurezza o uso non autorizzato del suo Account.";
static unsigned char eula_text_1446[] = "2. Informazioni accurate. Al momento della creazione dell\342\200\231Account, l\342\200\231utente si impegna a fornire un indirizzo";
