static unsigned char eula_text_1448[] = "informazioni in modo che siano sempre accurate.";
static unsigned char eula_text_1449[] = "3. Sospensione degli account. Aspyr Media pu\303\262, a sua esclusiva discrezione, sospendere o chiudere l\342\200\231Account";
static unsigned char eula_text_1450[] = "dell\342\200\231utente o il suo accesso al Servizio nel caso in cui la condotta dell\342\200\231utente, a nostro insindacabile";
static unsigned char eula_text_1451[] = "giudizio, non sia conforme al presente Contratto o per qualsiasi altra ragione.";
static unsigned char eula_text_1452[] = "4. Il Nome utente. Aspyr Media pu\303\262 obbligare l\342\200\231utente a cambiare uno dei suoi nickname se: (i) \303\250 il nome di";
