static unsigned char eula_text_1463[] = "concesso in licenza ovvero detiene i diritti su tutti i contenuti che appaiono nel Servizio, compresi gli";
static unsigned char eula_text_1464[] = "Account.";
static unsigned char eula_text_1465[] = "6. Contenuti e condotta dell\342\200\231utente";
static unsigned char eula_text_1466[] = "1. I Contenuti dell\342\200\231utente. Eventuali comunicazioni e materiali di qualsiasi tipo che l\342\200\231utente invia via";
