static unsigned char eula_text_1468[] = "compresi messaggi, commenti, fotografie, chat, e-mail, registrazioni vocali, dati, domande, feedback o";
static unsigned char eula_text_1469[] = "suggerimenti, sono noti come \342\200\234Contenuti\342\200\235 dell\342\200\231utente.";
