static unsigned char eula_text_1473[] = "modificare, tradurre, pubblicare, eseguire, mostrare, sviluppare, riprodurre, comunicare al pubblico e";
static unsigned char eula_text_1474[] = "rendere altrimenti disponibili i Contenuti in qualsiasi forma e con qualsiasi mezzo di comunicazione (sia ora";
static unsigned char eula_text_1475[] = "che in futuro), sia su base commerciale che non commerciale, ovunque nel mondo e in perpetuo.";
static unsigned char eula_text_1476[] = "2. Politica sulla condotta. L\342\200\231utente \303\250 responsabile della propria condotta in qualit\303\240 di utente del Servizio.";
static unsigned char eula_text_1477[] = "L\342\200\231utente accetta di non assumere un comportamento (compresa la condivisione di Contenuti) che:";
static unsigned char eula_text_1478[] = "* sia minaccioso, prepotente, diffamatorio, abusivo, osceno, lascivo, sessualmente provocatorio o allusivo,";
