static unsigned char eula_text_1483[] = "identit\303\240 di genere;";
static unsigned char eula_text_1484[] = "* costituisce spam (l\342\200\231invio dello stesso messaggio pi\303\271 volte o a pi\303\271 persone, o la condivisione o l\342\200\231invio";
static unsigned char eula_text_1485[] = "dello stesso contenuto pi\303\271 volte, saranno trattati come spam);";
