static unsigned char eula_text_1487[] = "attivit\303\240 che siano osceni o inappropriati;";
static unsigned char eula_text_1488[] = "* incoraggi o costituisca un comportamento che non supporta un ambiente sicuro e confortevole per tutti gli";
static unsigned char eula_text_1489[] = "utenti, il che pu\303\262 includere, per esempio, il bullismo, l\342\200\231esercitazione della giustizia privata, la messa in";
static unsigned char eula_text_1490[] = "atto di qualsiasi comportamento o attivit\303\240 che siano minacciosi, dannosi, molesti, abusivi, volgari, odiosi,";
static unsigned char eula_text_1491[] = "diffamatori, osceni, sessualmente provocatori, allusivi o espliciti, incendiari, blasfemi, discutibili dal";
static unsigned char eula_text_1492[] = "punto di vista razziale o etnico o discriminatori, o che in qualsiasi modo incoraggino una condotta";
