static unsigned char eula_text_1506[] = "* richiede informazioni di accesso ad altri utenti;";
static unsigned char eula_text_1507[] = "* effettua lo \342\200\234spoof\342\200\235 (l\342\200\231utilizzo di qualsiasi mezzo per camuffare la propria identit\303\240 online o alterare le";
