static unsigned char eula_text_1512[] = "* qualsiasi altra cosa che Aspyr Media, a suo insindacabile giudizio, ritenga offensiva o dannosa per il";
static unsigned char eula_text_1513[] = "Servizio o per l\342\200\231integrit\303\240 o l\342\200\231attivit\303\240 di Aspyr Media.";
static unsigned char eula_text_1514[] = "7. Mod";
static unsigned char eula_text_1515[] = "Le \342\200\234Mod\342\200\235 sono contenuti creati dagli utenti che possono essere utilizzati per modificare o migliorare";
static unsigned char eula_text_1516[] = "l\342\200\231esperienza di gioco di alcuni giochi e altri software che compongono il Servizio. La creazione, l\342\200\231uso e il";
static unsigned char eula_text_1517[] = "trasferimento di Mod da parte dell\342\200\231utente sono soggetti alla Politica sulla condotta di cui alla sezione 6.2";
static unsigned char eula_text_1518[] = "di cui sopra. Le Mod devono inoltre rispettare tutti i termini di servizio e gli altri accordi di terze parti";
static unsigned char eula_text_1519[] = "applicabili.";
static unsigned char eula_text_1520[] = "Aspyr Media si riserva il diritto di rimuovere qualsiasi Mod che ritenga, a sua esclusiva discrezione: (i) in";
static unsigned char eula_text_1521[] = "violazione del presente Contratto o di qualsiasi legge applicabile; o (ii) offensiva, inappropriata o";
static unsigned char eula_text_1522[] = "altrimenti discutibile.";
static unsigned char eula_text_1523[] = "Inviando le Mod ad Aspyr Media, l\342\200\231utente concede ad Aspyr Media una licenza mondiale, non esclusiva, esente";
static unsigned char eula_text_1524[] = "da royalty, interamente pagata, cedibile in sublicenza e trasferibile per utilizzare, riprodurre,";
static unsigned char eula_text_1525[] = "distribuire, creare opere derivate, eseguire pubblicamente, visualizzare pubblicamente, eseguire";
static unsigned char eula_text_1526[] = "digitalmente, realizzare, far realizzare, vendere, offrire in vendita e importare le Mod, in tutto o in";
static unsigned char eula_text_1527[] = "parte, per qualsiasi scopo e in qualsiasi forma, media o tecnologia, attualmente conosciuta o sviluppata in";
static unsigned char eula_text_1528[] = "futuro, ovunque nel mondo e in perpetuo. L\342\200\231utente accetta inoltre di rinunciare a qualsiasi diritto morale di";
static unsigned char eula_text_1529[] = "paternit\303\240, pubblicazione, reputazione o attribuzione sull\342\200\231uso da parte di Aspyr Media o di altri giocatori di";
static unsigned char eula_text_1530[] = "tali Mod.";
static unsigned char eula_text_1531[] = "Per alcuni giochi che fanno parte del Servizio, Aspyr Media utilizza Mod.io per gestire tutte le Mod di tali";
static unsigned char eula_text_1532[] = "giochi. Per poter accedere o rendere disponibili le Mod, \303\250 necessario registrare un account Mod.io. L\342\200\231account";
static unsigned char eula_text_1533[] = "Mod.io e l\342\200\231utilizzo del servizio Mod.io sono subordinati al consenso e al rispetto dei termini del Contratto";
static unsigned char eula_text_1534[] = "di licenza con l\342\200\231utente finale e dell\342\200\231Informativa sulla privacy di Mod.io. \303\210 possibile gestire il proprio";
static unsigned char eula_text_1535[] = "account, le impostazioni sulla privacy o cancellare e modificare i dati personali in qualsiasi momento";
static unsigned char eula_text_1536[] = "visitando il sito https://mod.io/members/privacy.";
static unsigned char eula_text_1537[] = "Se l\342\200\231utente \303\250 titolare di un diritto d\342\200\231autore o un suo rappresentante e ritiene che un contenuto di una Mod";
static unsigned char eula_text_1538[] = "violi i suoi diritti d\342\200\231autore, pu\303\262 inviare una segnalazione attraverso Mod.io o al nostro rappresentante per";
static unsigned char eula_text_1539[] = "il diritto d\342\200\231autore ai recapiti indicati nella Sezione 15.";
static unsigned char eula_text_1540[] = "8. Oggetti virtuali";
static unsigned char eula_text_1541[] = "Oggetti virtuali, costumi, contenuti scaricabili e \342\200\234gettoni\342\200\235 virtuali o monete (collettivamente, \342\200\234Oggetti";
static unsigned char eula_text_1542[] = "virtuali\342\200\235) possono essere offerti per l\342\200\231acquisto o altrimenti guadagnati attraverso il Servizio. La scelta";
static unsigned char eula_text_1543[] = "dell\342\200\231utente di effettuare un acquisto con valuta reale costituir\303\240 un\342\200\231offerta ad Aspyr Media per l\342\200\231acquisto ai";
static unsigned char eula_text_1544[] = "prezzi e ai termini indicati nel Servizio.";
static unsigned char eula_text_1545[] = "L\342\200\231utente accetta di non avere alcun diritto o titolo su alcun Oggetto virtuale. Aspyr Media non riconosce";
static unsigned char eula_text_1546[] = "alcun presunto trasferimento di Oggetti virtuali al di fuori del Servizio, n\303\251 la presunta vendita, il regalo";
static unsigned char eula_text_1547[] = "o il commercio nel \342\200\234mondo reale\342\200\235 di qualsiasi cosa appaia o abbia origine nel Servizio. L\342\200\231utente non pu\303\262";
static unsigned char eula_text_1548[] = "vendere Oggetti virtuali in cambio di denaro \342\200\234reale\342\200\235, n\303\251 scambiare tali Oggetti virtuali per un valore al di";
static unsigned char eula_text_1549[] = "fuori del Servizio, n\303\251 vendere, barattare o scambiare in altro modo gli Oggetti virtuali senza l\342\200\231esplicito";
static unsigned char eula_text_1550[] = "consenso scritto di Aspyr Media. Ai fini della chiarezza, gli Oggetti virtuali non hanno alcun valore reale e";
static unsigned char eula_text_1551[] = "sono concessi in licenza, non di propriet\303\240. Nessun diritto di propriet\303\240 o di altro tipo sugli Oggetti";
static unsigned char eula_text_1552[] = "virtuali spetter\303\240 all\342\200\231utente in nessun caso.";
static unsigned char eula_text_1553[] = "A meno che non sia richiesto dalla legge o altrimenti specificato sul Servizio o dalla Piattaforma di terze";
static unsigned char eula_text_1554[] = "parti attraverso la quale si accede al Servizio, tutte le vendite di Oggetti virtuali sono definitive quando";
static unsigned char eula_text_1555[] = "la transazione \303\250 stata elaborata e non saranno concessi rimborsi.";
static unsigned char eula_text_1556[] = "9. Servizi di supporto";
static unsigned char eula_text_1557[] = "Aspyr Media pu\303\262, a sua esclusiva discrezione, fornire all\342\200\231utente servizi di assistenza tecnica e al cliente";
static unsigned char eula_text_1558[] = "relativi al Servizio (\342\200\234Servizi di assistenza\342\200\235). Aspyr Media non \303\250 tenuta a fornire Servizi di assistenza se";
static unsigned char eula_text_1559[] = "non diversamente richiesto dalle leggi vigenti. La mancata fornitura o continuazione della fornitura dei";
static unsigned char eula_text_1560[] = "Servizi di assistenza non costituir\303\240 un inadempimento di Aspyr Media ai sensi del presente Contratto.";
static unsigned char eula_text_1561[] = "Qualsiasi codice software supplementare fornito all\342\200\231utente nell\342\200\231ambito dei Servizi di assistenza sar\303\240";
static unsigned char eula_text_1562[] = "considerato come parte del Servizio e, tra l\342\200\231utente e Aspyr Media, sar\303\240 e rimarr\303\240 di propriet\303\240 esclusiva di";
static unsigned char eula_text_1563[] = "Aspyr Media e sar\303\240 soggetto ai termini e alle condizioni del presente Contratto.";
static unsigned char eula_text_1564[] = "L\342\200\231assistenza clienti di Aspyr Media pu\303\262 essere contattata all\342\200\231indirizzo https://support.aspyr.com/hc/en-us.";
static unsigned char eula_text_1565[] = "Nessuna delle Piattaforme di terze parti o i loro proprietari hanno alcun obbligo, in nessuna circostanza, di";
static unsigned char eula_text_1566[] = "fornire Servizi di assistenza in relazione al Servizio. L\342\200\231utente accetta di rivolgersi esclusivamente ad";
static unsigned char eula_text_1567[] = "Aspyr Media in relazione ai Servizi di assistenza.";
static unsigned char eula_text_1568[] = "10. Termine e cessazione";
static unsigned char eula_text_1569[] = "La durata del presente Contratto decorre dal momento in cui l\342\200\231utente scarica o utilizza per la prima volta il";
static unsigned char eula_text_1570[] = "Servizio e continuer\303\240 per tutto il tempo in cui avr\303\240 copie del Servizio in suo possesso o acceder\303\240 al";
static unsigned char eula_text_1571[] = "Servizio, a seconda dei casi.";
static unsigned char eula_text_1572[] = "Senza pregiudizio per qualsiasi altro suo diritto, Aspyr Media potr\303\240 unilateralmente risolvere o modificare";
static unsigned char eula_text_1573[] = "il presente Contratto in qualsiasi momento e per qualsiasi motivo, senza alcun preavviso all\342\200\231utente. Ad";
static unsigned char eula_text_1574[] = "esempio, Aspyr Media potr\303\240 risolvere il presente Contratto e i diritti dell\342\200\231utente in relazione al Servizio,";
static unsigned char eula_text_1575[] = "qualora Aspyr Media, a sua esclusiva discrezione, interrompa il Servizio o parte di esso, smetta di";
static unsigned char eula_text_1576[] = "supportare o mantenere il Servizio o parte di esso, cessi di fornire aggiornamenti, non offra pi\303\271 il Servizio";
static unsigned char eula_text_1577[] = "in licenza o ritenga che l\342\200\231utente non abbia rispettato il presente Contratto.";
static unsigned char eula_text_1578[] = "Se Aspyr Media rescinde il presente Contratto sulla base del mancato rispetto dei suoi termini: (i) non verr\303\240";
static unsigned char eula_text_1579[] = "effettuato alcun rimborso; e (ii) l\342\200\231utente dovr\303\240 prontamente distruggere o cancellare tutte le copie del";
static unsigned char eula_text_1580[] = "Servizio in suo possesso. Se la modifica del presente Contratto da parte di Aspyr Media influisce in modo";
static unsigned char eula_text_1581[] = "sostanziale sui diritti dell\342\200\231utente in relazione al Servizio, cosa che Aspyr Media stabilir\303\240 a sua esclusiva";
static unsigned char eula_text_1582[] = "discrezione, Aspyr Media potr\303\240, ma senza alcun obbligo, notificare l\342\200\231utente inviando un\342\200\231e-mail all\342\200\231ultimo";
static unsigned char eula_text_1583[] = "indirizzo di posta elettronica noto registrato. Aspyr Media non si assumer\303\240 alcuna responsabilit\303\240 nel caso in";
static unsigned char eula_text_1584[] = "cui l\342\200\231utente non dovesse ricevere tale notifica.";
static unsigned char eula_text_1585[] = "Aspyr Media si riserva il diritto di modificare o interrompere, temporaneamente o permanentemente, il";
static unsigned char eula_text_1586[] = "Servizio (o qualsiasi parte del Servizio) con o senza preavviso in qualsiasi momento. L\342\200\231utente accetta che";
static unsigned char eula_text_1587[] = "Aspyr Media non sar\303\240 responsabile nei confronti dell\342\200\231utente o di terzi per qualsiasi modifica, sospensione o";
static unsigned char eula_text_1588[] = "interruzione del Servizio.";
static unsigned char eula_text_1589[] = "11. Monitoraggio";
static unsigned char eula_text_1590[] = "Aspyr Media si riserva il diritto di monitorare l\342\200\231uso del Servizio per determinare la conformit\303\240 al presente";
static unsigned char eula_text_1591[] = "Contratto, nonch\303\251 il diritto di modificare, rifiutare di pubblicare o rimuovere qualsiasi Contenuto,";
static unsigned char eula_text_1592[] = "informazione o materiale, in tutto o in parte, a propria esclusiva discrezione. Ci riserviamo il diritto di";
static unsigned char eula_text_1593[] = "rifiutare l\342\200\231accesso al Servizio a chiunque, per qualsiasi motivo, in qualsiasi momento.";
static unsigned char eula_text_1594[] = "Aspyr Media pu\303\262 monitorare i Contenuti e le altre comunicazioni dell\342\200\231utente per valutare la qualit\303\240 del";
static unsigned char eula_text_1595[] = "servizio ricevuto, la sua conformit\303\240 al Contratto, la sicurezza del Servizio o per altri motivi. L\342\200\231utente";
static unsigned char eula_text_1596[] = "accetta che tali attivit\303\240 di monitoraggio non gli daranno diritto ad alcuna azione legale o altro diritto in";
static unsigned char eula_text_1597[] = "relazione al modo in cui Aspyr Media o i suoi affiliati o agenti monitorano i Contenuti e le altre";
static unsigned char eula_text_1598[] = "comunicazioni dell\342\200\231utente e fanno rispettare o non fanno rispettare i termini del Contratto. In nessun caso";
static unsigned char eula_text_1599[] = "Aspyr Media o i suoi affiliati o agenti saranno responsabili di costi, danni, spese o altre responsabilit\303\240";
static unsigned char eula_text_1600[] = "sostenute dall\342\200\231utente a seguito di attivit\303\240 di monitoraggio da parte di Aspyr Media o dei suoi affiliati o";
static unsigned char eula_text_1601[] = "agenti.";
static unsigned char eula_text_1602[] = "12. Sicurezza della trasmissione e dell\342\200\231archiviazione dei dati";
static unsigned char eula_text_1603[] = "Le comunicazioni elettroniche che utilizzano il Servizio potrebbero non essere sempre criptate. L\342\200\231utente";
static unsigned char eula_text_1604[] = "riconosce che esiste il rischio che i dati, comprese le e-mail, le comunicazioni elettroniche e i dati";
static unsigned char eula_text_1605[] = "personali, possano essere consultati da terzi non autorizzati nelle comunicazioni tra l\342\200\231utente e Aspyr Media";
static unsigned char eula_text_1606[] = "o tra l\342\200\231utente e altre parti. Inoltre, le comunicazioni ed i Contenuti dell\342\200\231utente sul Servizio possono";
static unsigned char eula_text_1607[] = "essere pubblicamente disponibili ad altri.";
static unsigned char eula_text_1608[] = "Aspyr Media e i suoi affiliati e agenti sono autorizzati, ma non obbligati, a esaminare o conservare i";
static unsigned char eula_text_1609[] = "Contenuti e le altre comunicazioni dell\342\200\231utente.";
static unsigned char eula_text_1610[] = "13. Collegamenti ipertestuali";
static unsigned char eula_text_1611[] = "Il Servizio pu\303\262 contenere collegamenti ad altri siti e applicazioni software, anche attraverso annunci";
static unsigned char eula_text_1612[] = "pubblicitari (i \342\200\234Servizi collegati\342\200\235). Aspyr Media non controlla i Servizi collegati e Aspyr Media e i suoi";
static unsigned char eula_text_1613[] = "affiliati e agenti non rilasciano alcuna dichiarazione in merito al contenuto, all\342\200\231accuratezza, alla";
static unsigned char eula_text_1614[] = "sicurezza o alla privacy di tali Servizi collegati. Il fatto che Aspyr Media abbia fornito un collegamento a";
static unsigned char eula_text_1615[] = "un sito esterno non costituisce un\342\200\231approvazione, un\342\200\231autorizzazione, una sponsorizzazione o un\342\200\231affiliazione";
static unsigned char eula_text_1616[] = "rispetto a tali Servizi collegati, ai loro proprietari o ai loro fornitori. L\342\200\231utilizzo di qualsiasi";
static unsigned char eula_text_1617[] = "informazione, software o prodotto reperito su Internet comporta dei rischi che Aspyr Media invita a";
static unsigned char eula_text_1618[] = "comprendere prima di reperire, utilizzare, fare affidamento o acquistare qualsiasi cosa tramite Internet.";
static unsigned char eula_text_1619[] = "L\342\200\231utente accetta di non ritenere in nessun caso Aspyr Media, le sue affiliate o i suoi agenti responsabili di";
static unsigned char eula_text_1620[] = "eventuali perdite o danni causati dall\342\200\231uso o dall\342\200\231affidamento a contenuti, beni o servizi disponibili sui";
static unsigned char eula_text_1621[] = "Servizi collegati.";
static unsigned char eula_text_1622[] = "14. Marchi e copyright";
static unsigned char eula_text_1623[] = "Il Servizio \303\250 di propriet\303\240 di Aspyr Media ed \303\250 protetto da copyright statunitense e internazionale e da altre";
static unsigned char eula_text_1624[] = "leggi e trattati sulla propriet\303\240 intellettuale. Tutti i contenuti del Servizio, i marchi di fabbrica, i";
static unsigned char eula_text_1625[] = "marchi di servizio, i nomi commerciali, i loghi e le icone sono di propriet\303\240 di Aspyr Media o concessi in";
static unsigned char eula_text_1626[] = "licenza ad Aspyr Media. Nulla di quanto contenuto nel Servizio deve essere inteso come concessione di una";
static unsigned char eula_text_1627[] = "licenza o di un diritto all\342\200\231uso di un marchio visualizzato nel Servizio senza l\342\200\231autorizzazione scritta di";
static unsigned char eula_text_1628[] = "Aspyr Media o di una terza parte eventualmente titolare dei marchi visualizzati nel Servizio. L\342\200\231uso da parte";
