static unsigned char eula_text_1630[] = "quanto previsto dal presente Contratto, \303\250 severamente vietato.";
static unsigned char eula_text_1631[] = "La propriet\303\240 intellettuale visualizzata attraverso il Servizio \303\250 di propriet\303\240 di Aspyr Media o utilizzata con";
static unsigned char eula_text_1632[] = "il suo permesso. \303\210 vietato utilizzare o autorizzare l\342\200\231uso di tale propriet\303\240 intellettuale, a meno che non sia";
static unsigned char eula_text_1633[] = "specificamente consentito dal Contratto. Qualsiasi uso non autorizzato di questa propriet\303\240 intellettuale pu\303\262";
static unsigned char eula_text_1634[] = "violare le leggi sul diritto d\342\200\231autore, sui marchi, sulla privacy e sulla pubblicit\303\240, o altre norme e statuti.";
static unsigned char eula_text_1635[] = "15. Reclami relativi al copyright";
static unsigned char eula_text_1636[] = "Se siete titolari di diritti d\342\200\231autore o loro rappresentanti e ritenete che un contenuto del Servizio violi i";
static unsigned char eula_text_1637[] = "vostri diritti d\342\200\231autore, potete inviare una notifica DMCA per iscritto al nostro rappresentante per i diritti";
static unsigned char eula_text_1638[] = "d\342\200\231autore con le seguenti informazioni descritte di seguito. Nel momento in cui riceviamo una notifica di";
static unsigned char eula_text_1639[] = "violazione del diritto d\342\200\231autore, adottiamo le misure che riteniamo opportune, a nostra esclusiva discrezione,";
static unsigned char eula_text_1640[] = "compresa la rimozione dal Servizio dei materiali oggetto della presunta violazione o la disabilitazione";
static unsigned char eula_text_1641[] = "dell\342\200\231accesso pubblico agli stessi. Inoltre, per i trasgressori recidivi di contenuti protetti da copyright,";
static unsigned char eula_text_1642[] = "possiamo disabilitare il loro accesso al Servizio, rimuovere i loro Contenuti e chiudere il loro Account.";
static unsigned char eula_text_1643[] = "* Una firma fisica o elettronica di una persona autorizzata ad agire per conto del titolare di un diritto";
static unsigned char eula_text_1644[] = "esclusivo che si presume violato;";
static unsigned char eula_text_1645[] = "* Identificazione dell\342\200\231opera protetta da copyright che si ritiene sia stata violata o, nel caso in cui";
static unsigned char eula_text_1646[] = "vengano rivendicate pi\303\271 opere protette da copyright, un elenco di tali opere sul Servizio;";
static unsigned char eula_text_1647[] = "* Identificazione del materiale che si sostiene essere in violazione e che deve essere rimosso disattivato,";
static unsigned char eula_text_1648[] = "ragionevolmente sufficiente a permetterci di individuare il materiale;";
static unsigned char eula_text_1649[] = "* Informazioni ragionevolmente sufficienti per permetterci di contattarvi, come l\342\200\231e-mail, l\342\200\231indirizzo o il";
static unsigned char eula_text_1650[] = "numero di telefono;";
static unsigned char eula_text_1651[] = "* Una dichiarazione in cui si dichiara di ritenere in buona fede che l\342\200\231uso del materiale nel modo contestato";
static unsigned char eula_text_1652[] = "non \303\250 autorizzato dal proprietario del copyright, dal suo agente o dalla legge; e";
static unsigned char eula_text_1653[] = "* Una dichiarazione in cui si dichiara che le informazioni contenute nella notifica sono accurate e, sotto";
static unsigned char eula_text_1654[] = "pena di spergiuro, che siete autorizzati ad agire per conto del titolare di un diritto esclusivo che \303\250 stato";
static unsigned char eula_text_1655[] = "presumibilmente violato.";
static unsigned char eula_text_1656[] = "Il nostro rappresentante per i diritti d\342\200\231autore pu\303\262 essere contattato al seguente indirizzo postale o via";
static unsigned char eula_text_1657[] = "e-mail:";
static unsigned char eula_text_1658[] = "Rappresentante per il copyright";
static unsigned char eula_text_1659[] = "1250 S Capital of Texas Hwy, piano 6, Austin, TX 78746";
static unsigned char eula_text_1660[] = "Oppure via e-mail all\342\200\231indirizzo: legal@aspyr.com";
static unsigned char eula_text_1661[] = "16. Esclusione di garanzia";
