static unsigned char eula_text_1670[] = "Servizio, implica alcuna garanzia relativa al Servizio non espressamente dichiarata nel presente Contratto.";
static unsigned char eula_text_1671[] = "N\303\251 (a) le Piattaforme di terze parti, n\303\251 (b) Epic Games, Inc. (\342\200\234Epic\342\200\235) e/o Unity Software Inc. (\342\200\234Unity\342\200\235) (se";
static unsigned char eula_text_1672[] = "una parte del Servizio utilizza rispettivamente Unreal Engine o Unity Engine) sono parti del presente";
static unsigned char eula_text_1673[] = "Contratto o dell\342\200\231acquisto o della licenza del Servizio. Nessuna delle Piattaforme di Terze Parti o Epic o";
static unsigned char eula_text_1674[] = "Unity fornisce alcuna garanzia o assume alcuna garanzia o altro obbligo in relazione a: (i) il Servizio; o";
static unsigned char eula_text_1675[] = "(ii) qualsiasi reclamo, perdita, responsabilit\303\240, danno, costo o spesa attribuibile al Servizio, compresa";
static unsigned char eula_text_1676[] = "qualsiasi garanzia derivante da reclami di violazione della propriet\303\240 intellettuale o di diritti personali,";
