static unsigned char eula_text_1678[] = "Poich\303\251 alcuni stati o giurisdizioni non consentono l\342\200\231esclusione di garanzie implicite, l\342\200\231esclusione di cui";
static unsigned char eula_text_1679[] = "sopra potrebbe non essere applicabile all\342\200\231utente.";
