static unsigned char eula_text_1688[] = "confronti di piattaforme di terze parti, Epic o Unity, in base a qualsiasi teoria legale o di equit\303\240, in";
static unsigned char eula_text_1689[] = "qualsiasi parte del mondo, in relazione ai diritti concessi in licenza ai sensi del presente Contratto, al";
static unsigned char eula_text_1690[] = "possesso o all\342\200\231utilizzo del Servizio o al contenuto del Servizio. Qualsiasi reclamo derivante dal Servizio \303\250";
static unsigned char eula_text_1691[] = "soggetto alle limitazioni stabilite nel presente Contratto e pu\303\262 essere presentato solo contro Aspyr Media,";
static unsigned char eula_text_1692[] = "come descritto nelle sezioni 23 e 24 di seguito.";
static unsigned char eula_text_1693[] = "Poich\303\251 alcuni stati o giurisdizioni non consentono l\342\200\231esclusione o la limitazione di responsabilit\303\240 per danni";
static unsigned char eula_text_1694[] = "conseguenti o incidentali, in tali stati o giurisdizioni la responsabilit\303\240 di Aspyr Media e delle sue";
static unsigned char eula_text_1695[] = "affiliate sar\303\240 limitata nella misura massima consentita dalla legge.";
static unsigned char eula_text_1696[] = "18. Manleva";
static unsigned char eula_text_1697[] = "L\342\200\231utente accetta di manlevare e tenere indenne Aspyr Media e le sue affiliate, nonch\303\251 i rispettivi direttori,";
static unsigned char eula_text_1698[] = "funzionari, agenti e dipendenti da qualsiasi reclamo, richiesta, perdita, costo o spesa, comprese le spese";
static unsigned char eula_text_1699[] = "legali, avanzate da qualsiasi persona o entit\303\240 derivanti dalla violazione del presente Contratto, delle leggi";
static unsigned char eula_text_1700[] = "o dei regolamenti statali o federali o dei diritti di qualsiasi altra persona, compresa la violazione di";
static unsigned char eula_text_1701[] = "qualsiasi diritto d\342\200\231autore o di qualsiasi diritto di propriet\303\240 o di privacy. In nessuna circostanza, incluso";
static unsigned char eula_text_1702[] = "qualsiasi atto di negligenza, Aspyr Media, le sue affiliate o i rispettivi agenti e dipendenti saranno";
static unsigned char eula_text_1703[] = "responsabili per danni di qualsiasi tipo derivanti dall\342\200\231uso o dall\342\200\231impossibilit\303\240 di usare il Servizio.";
static unsigned char eula_text_1704[] = "19. Informazioni personali";
static unsigned char eula_text_1705[] = "Alcune informazioni personali e di altro tipo che raccogliamo, elaboriamo e condividiamo sono soggette alla";
static unsigned char eula_text_1706[] = "nostra Informativa sulla privacy.  Come condizione per l\342\200\231utilizzo del Servizio, l\342\200\231utente accetta i termini";
static unsigned char eula_text_1707[] = "dell\342\200\231Informativa sulla privacy, cos\303\254 come pu\303\262 essere modificata di volta in volta. La nostra Informativa";
static unsigned char eula_text_1708[] = "sulla privacy, qui incorporata per riferimento, si trova all\342\200\231indirizzo https://www.aspyr.com/privacy.";
static unsigned char eula_text_1709[] = "L\342\200\231utente accetta che il suo utilizzo del Servizio sia soggetto all\342\200\231Informativa sulla privacy.";
static unsigned char eula_text_1710[] = "20. Beneficiari terzi";
static unsigned char eula_text_1711[] = "L\342\200\231utente riconosce e accetta che le Piattaforme di terze parti, gli Editori di terze parti, Epic e Unity sono";
static unsigned char eula_text_1712[] = "beneficiari terzi del presente Contratto e che, in seguito all\342\200\231accettazione da parte dell\342\200\231utente dei termini";
static unsigned char eula_text_1713[] = "e delle condizioni del presente Contratto, una qualsiasi delle suddette terze parti avr\303\240 il diritto (e si";
static unsigned char eula_text_1714[] = "riterr\303\240 che abbia accettato il diritto) di far valere il presente Contratto come beneficiario terzo.";
static unsigned char eula_text_1715[] = "21. Informazioni richieste dalla legge";
static unsigned char eula_text_1716[] = "Aspyr Media si riserva il diritto di divulgare qualsiasi informazione, comprese le informazioni di";
static unsigned char eula_text_1717[] = "identificazione personale dell\342\200\231utente, se necessario per soddisfare qualsiasi legge, regolamento, procedura";
static unsigned char eula_text_1718[] = "legale o richiesta governativa. Aspyr Media si riserva il diritto di collaborare pienamente con le autorit\303\240";
static unsigned char eula_text_1719[] = "preposte all\342\200\231applicazione della legge o con gli ordini del tribunale che richiedano o ordinino ad Aspyr Media";
static unsigned char eula_text_1720[] = "di rivelare l\342\200\231identit\303\240 di qualsiasi utente ritenuto in violazione del presente Contratto.";
static unsigned char eula_text_1721[] = "Accettando il presente Contratto, l\342\200\231utente rinuncia a tutti i diritti e accetta di tenere indenne Aspyr Media";
static unsigned char eula_text_1722[] = "da qualsiasi reclamo derivante da qualsiasi azione intrapresa da Aspyr Media durante o come risultato delle";
static unsigned char eula_text_1723[] = "sue indagini o da qualsiasi azione intrapresa come conseguenza di indagini da parte di Aspyr Media o delle";
static unsigned char eula_text_1724[] = "autorit\303\240 di polizia.";
static unsigned char eula_text_1725[] = "22. Controlli sulle esportazioni";
static unsigned char eula_text_1726[] = "L\342\200\231utente non pu\303\262 utilizzare, accedere o esportare o riesportare in altro modo il Servizio, salvo quanto";
static unsigned char eula_text_1727[] = "autorizzato dalla legge degli Stati Uniti e dalle leggi della giurisdizione in cui il Servizio \303\250 stato";
static unsigned char eula_text_1728[] = "ottenuto. In particolare, ma senza limitazioni, il Servizio non pu\303\262 essere esportato, riesportato o reso";
static unsigned char eula_text_1729[] = "disponibile in altro modo: (a) in qualsiasi paese o regione sottoposta a embargo da parte del governo degli";
static unsigned char eula_text_1730[] = "Stati Uniti; o (b) a chiunque figuri nella Specially Designated Nationals List del Dipartimento del Tesoro";
static unsigned char eula_text_1731[] = "degli Stati Uniti o nelle Denied person List o Entity List del Dipartimento del Commercio degli Stati Uniti o";
static unsigned char eula_text_1732[] = "nell\342\200\231elenco consolidato delle persone, dei gruppi e delle entit\303\240 soggetti a sanzioni dell\342\200\231UE Utilizzando il";
static unsigned char eula_text_1733[] = "Servizio, l\342\200\231utente dichiara e garantisce di non trovarsi in uno dei suddetti Paesi o in uno dei suddetti";
static unsigned char eula_text_1734[] = "elenchi.";
static unsigned char eula_text_1735[] = "23. Legge applicabile; mediazione; giurisdizione";
static unsigned char eula_text_1736[] = "Il Contratto e tutti i futuri accordi stipulati dall\342\200\231utente con Aspyr Media, se non diversamente indicato in";
static unsigned char eula_text_1737[] = "tali accordi, saranno disciplinati dalle leggi dello Stato del Texas. Ci\303\262 vale indipendentemente dal fatto";
static unsigned char eula_text_1738[] = "che l\342\200\231utente risieda o faccia affari con Aspyr Media, o con una qualsiasi delle sue affiliate o agenti, nello";
static unsigned char eula_text_1739[] = "Stato del Texas o altrove. A meno che una controversia non sia regolata dai termini della Sezione 24 qui";
static unsigned char eula_text_1740[] = "sotto, l\342\200\231utente accetta di sottoporsi alla giurisdizione personale ed esclusiva dei tribunali statali e";
static unsigned char eula_text_1741[] = "federali situati nella citt\303\240 di Austin, Texas, Stati Uniti.";
static unsigned char eula_text_1742[] = "Solo per gli utenti dell\342\200\231UE: In caso di controversie relative all\342\200\231interpretazione, all\342\200\231esecuzione o alla";
static unsigned char eula_text_1743[] = "validit\303\240 del presente Contratto, \303\250 possibile cercare una soluzione amichevole prima di intraprendere";
static unsigned char eula_text_1744[] = "qualsiasi azione legale. \303\210 possibile presentare un reclamo ad Aspyr Media inviando un messaggio via e-mail";
static unsigned char eula_text_1745[] = "all\342\200\231indirizzo legal@aspyr.com. In caso di insuccesso, \303\250 possibile, entro un anno dalla richiesta fallita,";
static unsigned char eula_text_1746[] = "ricorrere a una procedura di risoluzione alternativa delle controversie presentando un reclamo online sul";
static unsigned char eula_text_1747[] = "sito web della Commissione europea dedicato alla risoluzione delle controversie";
static unsigned char eula_text_1748[] = "online:https://webgate.ec.europa.eu/odr/main/index.cfm?event=main.home.chooseLanguage. Nel caso in cui la";
static unsigned char eula_text_1749[] = "risoluzione extragiudiziale delle controversie fallisca, la controversia pu\303\262 essere portata davanti ai";
static unsigned char eula_text_1750[] = "tribunali competenti.";
static unsigned char eula_text_1751[] = "24. Arbitrato vincolante";
static unsigned char eula_text_1752[] = "Qualsiasi controversia o reclamo relativo all\342\200\231utilizzo del Servizio da parte dell\342\200\231utente (ciascuno, un";
static unsigned char eula_text_1753[] = "\342\200\234reclamo\342\200\235) sar\303\240 risolto mediante arbitrato vincolante, piuttosto che in tribunale (ad eccezione del fatto che";
static unsigned char eula_text_1754[] = "l\342\200\231utente pu\303\262 far valere i propri diritti in un tribunale per le controversie di modesta entit\303\240 se le sue";
static unsigned char eula_text_1755[] = "richieste sono ammissibili). L\342\200\231utente accetta che ogni Reclamo deve essere presentato singolarmente.";
static unsigned char eula_text_1756[] = "L\342\200\231UTENTE E ASPYR MEDIA ACCETTANO CHE: (i) NON ESISTE ALCUN DIRITTO O AUTORIT\303\200";
static unsigned char eula_text_1757[] = "CHE IMPONGA CHE UN EVENTUALE CONTENZIOSO SIA ARBITRATO SU BASE DI CLASS";
static unsigned char eula_text_1758[] = "ACTION O CHE VENGANO UTILIZZATE LE PROCEDURE DI CLASS ACTION; (ii)";
static unsigned char eula_text_1759[] = "NON ESISTE ALCUN DIRITTO O AUTORIT\303\200 CHE IMPONGA CHE ALCUNE CONTROVERSIE";
static unsigned char eula_text_1760[] = "SIANO PORTATE AVANTI IN QUALIT\303\200 DI RAPPRESENTANTE O COME AVVOCATO GENERALE PRIVATO;";
static unsigned char eula_text_1761[] = " E (iii) NESSUN ARBITRATO PU\303\222 ESSERE CONGIUNTO CON ALTRI ARBITRATI.";
static unsigned char eula_text_1762[] = "La legge federale sull\342\200\231arbitrato e la legge federale sull\342\200\231arbitrato si applicano al presente Contratto e alla";
static unsigned char eula_text_1763[] = "presente clausola arbitrale vincolante.";
static unsigned char eula_text_1764[] = "L\342\200\231arbitrato \303\250 un processo che non prevede giudici o giurie: un arbitro esaminer\303\240 le argomentazioni della";
static unsigned char eula_text_1765[] = "controversia e assegner\303\240 i danni e gli altri provvedimenti proprio come farebbe un tribunale. L\342\200\231arbitro deve";
static unsigned char eula_text_1766[] = "attenersi al presente Contratto come farebbe un tribunale. Il controllo del tribunale sul lodo arbitrale \303\250";
static unsigned char eula_text_1767[] = "limitato dalla legge federale sull\342\200\231arbitrato.";
static unsigned char eula_text_1768[] = "Per avviare un arbitrato, l\342\200\231utente deve inviare un\342\200\231e-mail all\342\200\231indirizzo legal@aspyr.com descrivendo il";
static unsigned char eula_text_1769[] = "proprio Reclamo e richiedendo l\342\200\231arbitrato, oppure possiamo fare lo stesso inviando una comunicazione scritta";
static unsigned char eula_text_1770[] = "di richiesta di arbitrato al suo indirizzo. Il procedimento sar\303\240 condotto tramite JAMS, utilizzando le sue";
static unsigned char eula_text_1771[] = "regole e procedure arbitrali semplificate. \303\210 possibile consultare queste regole su jamsadr.com o chiamando il";
static unsigned char eula_text_1772[] = "numero 800-352-5267. Il pagamento delle spese di deposito iniziali sar\303\240 effettuato dalla parte che presenta";
static unsigned char eula_text_1773[] = "la richiesta di indennizzo, mentre le altre spese di deposito e le altre spese saranno ripartite come";
static unsigned char eula_text_1774[] = "previsto dal regolamento JAMS. L\342\200\231arbitrato si svolger\303\240 ad Austin, Texas, Stati Uniti, a meno che le Parti non";
static unsigned char eula_text_1775[] = "concordino apparizioni in video, telefono o connessione internet.";
static unsigned char eula_text_1776[] = "Salvo quanto diversamente stabilito di seguito, l\342\200\231utente pu\303\262 richiedere qualsiasi rimedio disponibile ai";
static unsigned char eula_text_1777[] = "sensi delle leggi federali, statali o locali in un\342\200\231azione arbitrale. Nell\342\200\231ambito dell\342\200\231arbitrato, sia voi che";
static unsigned char eula_text_1778[] = "Aspyr Media avrete l\342\200\231opportunit\303\240 di scoprire informazioni non privilegiate rilevanti per il reclamo.";
static unsigned char eula_text_1779[] = "L\342\200\231arbitro fornir\303\240 una dichiarazione scritta della decisione dell\342\200\231arbitro in merito al Reclamo, il lodo emesso";
static unsigned char eula_text_1780[] = "(comprese le spese legali e i costi sostenuti), nonch\303\251 i risultati e le conclusioni dell\342\200\231arbitro su cui si";
static unsigned char eula_text_1781[] = "basa la decisione dell\342\200\231arbitro.";
static unsigned char eula_text_1782[] = "Nonostante i termini della presente sezione, ciascuno di noi pu\303\262 intentare una causa in tribunale per";
static unsigned char eula_text_1783[] = "ottenere un\342\200\231equa riparazione, per qualsiasi abuso o violazione dei diritti di propriet\303\240 intellettuale, o per";
static unsigned char eula_text_1784[] = "qualsiasi reclamo relativo a, o derivante da, accuse di furto, pirateria, violazione della privacy o uso non";
static unsigned char eula_text_1785[] = "autorizzato del Servizio.";
static unsigned char eula_text_1786[] = "ACCETTANDO QUESTA DISPOSIZIONE DI ARBITRATO, L\342\200\231UTENTE COMPRENDE CHE";
static unsigned char eula_text_1787[] = "L\342\200\231UTENTE E Aspyr Media RINUNCIANO AL DIRITTO DI CEDERE IN GIUDIZIO E DIAVERE UN PROCESSO CON GIURATO.";
static unsigned char eula_text_1788[] = "L\342\200\231utente e Aspyr Media concordano che se una qualsiasi parte della presente Sezione \303\250 ritenuta illegale o";
static unsigned char eula_text_1789[] = "inapplicabile, tale parte sar\303\240 separata e la parte restante della Sezione avr\303\240 pieno vigore ed effetto.";
static unsigned char eula_text_1790[] = "25. Termini vari";
static unsigned char eula_text_1791[] = "1. Revisioni del Contratto. Il presente Contratto pu\303\262 essere rivisto solo per iscritto da Aspyr Media, o da";
static unsigned char eula_text_1792[] = "Aspyr Media, dalla pubblicazione di una nuova versione sul Servizio.";
static unsigned char eula_text_1793[] = "2. Forza maggiore. Aspyr Media non \303\250 responsabile di eventuali ritardi o mancate prestazioni derivanti da";
static unsigned char eula_text_1794[] = "circostanze impreviste o da cause al di fuori del controllo diAspyr Media, tra cui ,a titolo esemplificativo";
static unsigned char eula_text_1795[] = "e non esaustivo,  cause di forza maggiore, guerre, terrorismo, sommosse, embarghi, atti di autorit\303\240 civili o";
static unsigned char eula_text_1796[] = "militari, incendi, inondazioni, incidenti, scioperi o carenza di mezzi di trasporto, carburante, energia,";
static unsigned char eula_text_1797[] = "manodopera o materiali.";
static unsigned char eula_text_1798[] = "3. Nessuna partnership. L\342\200\231utente accetta che non esiste alcun rapporto di joint venture, partnership, impiego";
static unsigned char eula_text_1799[] = "o agenzia tra l\342\200\231utente e Aspyr Media come risultato del presente Contratto o dell\342\200\231utilizzo del Servizio da";
static unsigned char eula_text_1800[] = "parte dell\342\200\231utente.";
static unsigned char eula_text_1801[] = "4. Cessione. Aspyr Media potr\303\240 cedere il presente Contratto, in tutto o in parte, a qualsiasi persona o";
static unsigned char eula_text_1802[] = "entit\303\240 in qualsiasi momento con o senza il consenso dell\342\200\231utente. L\342\200\231utente non pu\303\262 cedere il Contratto senza";
static unsigned char eula_text_1803[] = "Aspyr Mediaprevio consenso scritto dell\342\200\231utente, e qualsiasi cessione non autorizzata da parte dell\342\200\231utente";
static unsigned char eula_text_1804[] = "sar\303\240 nulla e non valida.";
static unsigned char eula_text_1805[] = "5. Clausola di salvaguardia. Se una qualsiasi parte del presente Contratto \303\250 ritenuta nulla, non valida o";
static unsigned char eula_text_1806[] = "inapplicabile, tale parte sar\303\240 eliminata e la parte restante del Contratto avr\303\240 pieno vigore ed efficacia.";
static unsigned char eula_text_1807[] = "6. Onorari degli avvocati. Nel caso in cui una delle parti abbia avviato un contenzioso in relazione al";
static unsigned char eula_text_1808[] = "presente Contratto, la parte che prevale in tale contenzioso avr\303\240 il diritto di recuperare dall\342\200\231altra parte";
static unsigned char eula_text_1809[] = "tutti i costi ragionevoli, le parcelle degli avvocati e le altre spese sostenute da tale parte prevalente nel";
static unsigned char eula_text_1810[] = "contenzioso.";
static unsigned char eula_text_1811[] = "7. Nessuna rinuncia. La mancata applicazione da parte nostra di una qualsiasi disposizione del presente";
static unsigned char eula_text_1812[] = "Contratto non potr\303\240 in alcun modo essere interpretata come una rinuncia presente o futura a tale";
static unsigned char eula_text_1813[] = "disposizione, n\303\251 pregiudicare in alcun modo il diritto di qualsiasi parte di applicare successivamente tale";
static unsigned char eula_text_1814[] = "disposizione. L\342\200\231espressa rinuncia da parte nostra a qualsiasi disposizione, condizione o requisito del";
static unsigned char eula_text_1815[] = "presente Contratto non costituir\303\240 una rinuncia a qualsiasi obbligo futuro di rispettare tale disposizione,";
static unsigned char eula_text_1816[] = "condizione o requisito.";
static unsigned char eula_text_1817[] = "8. Rimedi equitativi. Con la presente l\342\200\231utente accetta che Aspyr Media sarebbe irrimediabilmente danneggiata";
static unsigned char eula_text_1818[] = "se i termini del presente Contratto non venissero applicati in modo specifico, e pertanto l\342\200\231utente accetta";
static unsigned char eula_text_1819[] = "che avremo il diritto, senza cauzioni, altre garanzie o prove di danni, di ricorrere ad appropriati rimedi";
static unsigned char eula_text_1820[] = "equitativi in relazione alle violazioni del presente Contratto, oltre a tutti gli altri rimedi di cui";
static unsigned char eula_text_1821[] = "potremmo disporre ai sensi delle leggi applicabili. Inoltre, l\342\200\231utente accetta che il suo unico rimedio, se";
static unsigned char eula_text_1822[] = "del caso, per qualsiasi violazione del presente Contratto sar\303\240 esclusivamente il risarcimento dei danni in";
static unsigned char eula_text_1823[] = "denaro. Con la presente l\342\200\231utente rinuncia a qualsiasi diritto di ottenere un provvedimento ingiuntivo o";
static unsigned char eula_text_1824[] = "equitativo ai sensi del presente Contratto.";
static unsigned char eula_text_1825[] = "9. Intero Accordo. Il presente Contratto, inclusi i documenti espressamente incorporati per riferimento,";
static unsigned char eula_text_1826[] = "costituisce l\342\200\231intero accordo tra l\342\200\231utente e Aspyr Media in relazione al Servizio e sostituisce tutte le";
static unsigned char eula_text_1827[] = "comunicazioni precedenti o contemporanee, siano esse elettroniche, orali o scritte, tra l\342\200\231utente e Aspyr";
static unsigned char eula_text_1828[] = "Media con riferimento al Servizio.";
static unsigned char eula_text_1829[] = "L\342\200\231utente deve accettare i termini e le condizioni prima di poter giocare o utilizzare i Servizi.";
static unsigned char eula_text_1830[] = "Acuerdo de licencia de usuario final";
static unsigned char eula_text_1831[] = "MODIFICADO POR \303\232LTIMA VEZ EL 2 de octubre de 2023";
static unsigned char eula_text_1832[] = "Importante: Lea este acuerdo detenidamente.";
static unsigned char eula_text_1833[] = "La secci\303\263n 24 de este Acuerdo de licencia de usuario final contiene una cl\303\241usula de arbitraje vinculante y";
static unsigned char eula_text_1834[] = "una renuncia a demanda colectiva. Si vive en los Estados Unidos, esta Secci\303\263n afecta sus derechos sobre c\303\263mo";
static unsigned char eula_text_1835[] = "resolver controversias que pueda tener con nosotros.";
static unsigned char eula_text_1836[] = "L\303\251alo detenidamente.";
static unsigned char eula_text_1837[] = "Este Acuerdo de licencia de usuario final (el \342\200\234Acuerdo\342\200\235) se celebra entre usted y Aspyr Media, Inc. (\342\200\234Aspyr";
static unsigned char eula_text_1838[] = "Media\342\200\235) y aplica a las aplicaciones de software de videojuegos desarrolladas o publicadas por Aspyr Media y";
static unsigned char eula_text_1839[] = "al sitio web de Aspyr Media ubicado en https:/ /www.aspyr.com/ (de forma individual y colectiva, el";
static unsigned char eula_text_1840[] = "\342\200\234Servicio\342\200\235).";
static unsigned char eula_text_1841[] = "Ciertas aplicaciones de software desarrolladas por Aspyr Media son publicadas por terceros (\342\200\234Editores";
static unsigned char eula_text_1842[] = "externos\342\200\235) y est\303\241n sujetas al acuerdo de licencia de usuario final de dichos terceros u otros t\303\251rminos. Estas";
static unsigned char eula_text_1843[] = "aplicaciones no est\303\241n incluidas en la definici\303\263n de \342\200\234Servicio\342\200\235.";
static unsigned char eula_text_1844[] = "1. Aceptaci\303\263n de los t\303\251rminos";
static unsigned char eula_text_1845[] = "Al continuar utilizando el Servicio, usted acepta lo siguiente:";
static unsigned char eula_text_1846[] = "1. Usted comprende y tiene la intenci\303\263n de que este Acuerdo es un acuerdo legalmente vinculante y el";
static unsigned char eula_text_1847[] = "equivalente a un contrato escrito y firmado;";
static unsigned char eula_text_1848[] = "2. Usted deber\303\241 utilizar el Servicio de acuerdo con las leyes y regulaciones aplicables y de acuerdo con los";
static unsigned char eula_text_1849[] = "t\303\251rminos y las condiciones de este Acuerdo, seg\303\272n Aspyr Media lo modifique ocasionalmente; y";
static unsigned char eula_text_1850[] = "3. Usted comprende, acepta y ha recibido este Acuerdo y sus t\303\251rminos y condiciones, y reconoce y demuestra";
static unsigned char eula_text_1851[] = "que tiene acceder a este Acuerdo.";
static unsigned char eula_text_1852[] = "Aspyr Media se reserva el derecho de actualizar o modificar este Acuerdo en cualquier momento mediante la";
static unsigned char eula_text_1853[] = "publicaci\303\263n de la versi\303\263n m\303\241s reciente del Acuerdo en nuestro sitio web mostrando una nueva Fecha de";
static unsigned char eula_text_1854[] = "vigencia. Dichos cambios en el Acuerdo entrar\303\241n en vigor a partir de la Fecha de entrada en vigencia.";
static unsigned char eula_text_1855[] = "Su uso continuado del Servicio despu\303\251s de que publiquemos cualquier cambio en este Acuerdo significa que";
static unsigned char eula_text_1856[] = "acepta dichos cambios. Si no est\303\241 de acuerdo con los t\303\251rminos y condiciones de este Acuerdo, suspenda el uso";
static unsigned char eula_text_1857[] = "del Servicio.";
static unsigned char eula_text_1858[] = "2. Licencia de Aspyr Media para usted";
static unsigned char eula_text_1859[] = "Aspyr Media le otorga una licencia personal \303\272nica, no exclusiva, intransferible y limitada para acceder y";
static unsigned char eula_text_1860[] = "utilizar el Servicio. Esta licencia est\303\241 condicionada a que usted cumpla de forma continua con los t\303\251rminos y";
static unsigned char eula_text_1861[] = "condiciones de este Acuerdo. Usted no puede alquilar, arrendar, prestar, vender, transferir, redistribuir ni";
static unsigned char eula_text_1862[] = "sublicenciar el Servicio y, si vende o transfiere de otro modo un dispositivo en el que est\303\251 instalada";
static unsigned char eula_text_1863[] = "cualquier parte del Servicio a un tercero, debe eliminar el Servicio de dicho dispositivo antes de hacerlo.";
static unsigned char eula_text_1864[] = "No puede copiar, descompilar, realizar ingenier\303\255a inversa, desensamblar, intentar obtener el c\303\263digo fuente,";
static unsigned char eula_text_1865[] = "modificar o crear trabajos derivados del Servicio, cualquier actualizaci\303\263n o cualquier parte del mismo,";
static unsigned char eula_text_1866[] = "excepto y solo en la medida en que cualquier restricci\303\263n anterior est\303\241 prohibida por la ley aplicable o en la";
static unsigned char eula_text_1867[] = "medida en que lo permitan los t\303\251rminos de licencia que rigen el uso de cualquier componente de c\303\263digo abierto";
static unsigned char eula_text_1868[] = "incluido con el Servicio.";
static unsigned char eula_text_1869[] = "3. Mensajes provenientes de Aspyr Media";
static unsigned char eula_text_1870[] = "Usted comprende que puede recibir comunicaciones comerciales de parte de Aspyr Media a trav\303\251s del Servicio o";
static unsigned char eula_text_1871[] = "por correo electr\303\263nico, tales como anuncios de productos y de otro tipo, y avisos administrativos. Usted";
static unsigned char eula_text_1872[] = "acepta que estas comunicaciones no son \342\200\234anuncios comerciales por correo electr\303\263nico no solicitados\342\200\235 y acepta";
static unsigned char eula_text_1873[] = "recibirlas.";
static unsigned char eula_text_1874[] = "Los mensajes de correo electr\303\263nico de marketing ir\303\241n acompa\303\261ados de instrucciones para darse de baja.";
