static unsigned char eula_text_1899[] = "todav\303\255a es menor de edad en su jurisdicci\303\263n, su padre o tutor legal debe crear una Cuenta con nosotros para";
static unsigned char eula_text_1900[] = "que pueda acceder y utilizar el Servicio.";
static unsigned char eula_text_1901[] = "Puede crear una Cuenta registr\303\241ndose a trav\303\251s de un formulario de registro en el Servicio o, en algunos";
