static unsigned char eula_text_1921[] = "6. Se proh\303\255ben las ventas y transferencias de cuentas. Usted no puede comprar, vender, ceder ni intercambiar";
static unsigned char eula_text_1922[] = "ninguna Cuenta, ni intentar comprar, vender, ceder ni comerciar ninguna Cuenta. Aspyr Media posee, tiene";
static unsigned char eula_text_1923[] = "licencia o tiene derechos sobre todo el contenido que aparece en el Servicio, incluidas las Cuentas.";
static unsigned char eula_text_1924[] = "6. Su contenido y conducta";
static unsigned char eula_text_1925[] = "1. Su contenido. Cualquier comunicaci\303\263n o material de cualquier tipo que usted env\303\255e por correo electr\303\263nico,";
