static unsigned char eula_text_1927[] = "Servicio, incluidos mensajes, comentarios, fotograf\303\255as, chat, correos electr\303\263nicos, grabaciones de voz,";
static unsigned char eula_text_1928[] = "datos, preguntas, comentarios o sugerencias se conocen como su \342\200\234Contenido\342\200\235.";
static unsigned char eula_text_1929[] = "Aspyr Media no es propietaria de su Contenido. Al publicar Contenido, usted declara (i) que es el propietario";
