static unsigned char eula_text_1931[] = "para usar, reutilizar, copiar, adaptar, abreviar, enmendar, distribuir, modificar, traducir, publicar,";
static unsigned char eula_text_1932[] = "realizar, mostrar, desarrollar, reproducir, comunicar al p\303\272blico y hacer que su Contenido est\303\251 disponible en";
static unsigned char eula_text_1933[] = "cualquier forma y por cualquier medio, ya sea conocido ahora o ideado en el futuro, ya sea con fines";
static unsigned char eula_text_1934[] = "comerciales o no comerciales en cualquier parte del mundo a perpetuidad.";
static unsigned char eula_text_1935[] = "2. Pol\303\255tica de conducta. Usted es responsable de su conducta como usuario del Servicio. Usted acepta que no";
