static unsigned char eula_text_1937[] = "caracter\303\255sticas:";
static unsigned char eula_text_1938[] = "* Sea amenazante, intimidante, difamatorio, abusivo, obsceno, lascivo, sexualmente provocativo o sugerente,";
static unsigned char eula_text_1939[] = "pornogr\303\241fico o que de cualquier manera pueda generar cualquier responsabilidad civil o penal en virtud de la";
static unsigned char eula_text_1940[] = "ley aplicable.";
static unsigned char eula_text_1941[] = "* Sea o podr\303\255a ser tomado como insulto, incitaci\303\263n al odio o ataques a individuos o grupos por motivos de";
