static unsigned char eula_text_1944[] = "contenido varias veces se considerar\303\241 spam).";
static unsigned char eula_text_1945[] = "* Sea una incitaci\303\263n o publicidad de cualquier conducta personal, producto comercial o actividad lasciva o";
static unsigned char eula_text_1946[] = "inapropiada.";
static unsigned char eula_text_1947[] = "* Alienta o constituye un comportamiento que no respalda un entorno seguro y c\303\263modo para todos los usuarios,";
static unsigned char eula_text_1948[] = "cuya conducta puede incluir, entre otras, intimidaci\303\263n, vigilantismo, participar en cualquier conducta o";
static unsigned char eula_text_1949[] = "actividad que sea amenazante, da\303\261ina, acosadora, abusiva, vulgar, cargada de odio, difamatoria, lasciva,";
static unsigned char eula_text_1950[] = "sexualmente provocativa, sugerente o expl\303\255cita, incendiaria, profana, racial o \303\251tnicamente objetable o";
static unsigned char eula_text_1951[] = "discriminatoria, o que de cualquier manera fomente conductas inapropiadas, irrespetuosas, abusivas o ilegales";
static unsigned char eula_text_1952[] = "o que de otro modo haga que el Servicio sea una experiencia inc\303\263moda para cualquier persona.";
static unsigned char eula_text_1953[] = "* Restringe, inhibe o disuade a cualquier otro usuario de utilizar el Servicio.";
