static unsigned char eula_text_2036[] = "correo electr\303\263nico conocida registrada. Aspyr Media no tiene ninguna responsabilidad si usted no recibe esta";
static unsigned char eula_text_2037[] = "notificaci\303\263n.";
static unsigned char eula_text_2038[] = "Aspyr Media se reserva el derecho de modificar o discontinuar, de forma temporal o permanente, el Servicio o";
static unsigned char eula_text_2039[] = "cualquier parte de este, con o sin previo aviso en cualquier momento. Usted acepta que Aspyr Media no ser\303\241";
